const cache = new Map();
const inflight = new Map();

const cacheKey = (token, url) => `${token || ''}:${url}`;

export const fetchSecureMediaBlobUrl = async (url, token) => {
  if (!url || !token) {
    throw new Error('Missing url or token for secure media fetch');
  }

  const key = cacheKey(token, url);
  if (cache.has(key)) {
    return cache.get(key);
  }

  if (inflight.has(key)) {
    return inflight.get(key);
  }

  const promise = (async () => {
    const response = await fetch(url, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    if (!response.ok) {
      throw new Error(`Failed to fetch media: ${response.status}`);
    }

    const blob = await response.blob();
    const objectUrl = URL.createObjectURL(blob);
    cache.set(key, objectUrl);
    inflight.delete(key);
    return objectUrl;
  })().catch((err) => {
    inflight.delete(key);
    throw err;
  });

  inflight.set(key, promise);
  return promise;
};

export const releaseSecureMediaBlobUrl = (url, token) => {
  if (!url || !token) return;
  const key = cacheKey(token, url);
  const cached = cache.get(key);
  if (cached && cached.startsWith('blob:')) {
    URL.revokeObjectURL(cached);
  }
  cache.delete(key);
  inflight.delete(key);
};

export const clearMediaCache = () => {
  cache.forEach((objectUrl) => {
    if (objectUrl && objectUrl.startsWith('blob:')) {
      URL.revokeObjectURL(objectUrl);
    }
  });
  cache.clear();
  inflight.clear();
};
