import React from "react";
import {
  Dialog,
  DialogContent,
  DialogActions,
  CircularProgress,
  Box,
  useTheme,
  useMediaQuery,
  Slide,
  IconButton,
  Typography,
  Button
} from "@mui/material";
import LogoutOutlinedIcon from "@mui/icons-material/LogoutOutlined";
import CloseIcon from "@mui/icons-material/Close";

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const LogoutModal = ({ open, loading = false, onConfirm, onClose }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  const handleClose = () => {
    if (!loading) onClose?.();
  };

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      fullScreen={isMobile}
      TransitionComponent={isMobile ? Transition : undefined}
      fullWidth
      maxWidth="xs"
      keepMounted
      disableEscapeKeyDown={loading}
      PaperProps={{
        sx: {
          backgroundColor: "#1A1A1A",
          backgroundImage: "none",
          borderRadius: isMobile ? 0 : "12px",
          border: isMobile ? "none" : "1px solid rgba(255, 255, 255, 0.1)",
          boxShadow: "0 8px 32px rgba(0,0,0,0.5)",
          textAlign: "center",
          p: 2,
        },
      }}
    >
      <Box sx={{ 
        display: "flex", 
        flexDirection: "column", 
        height: "100%",
        justifyContent: "center",
        position: "relative"
      }}>
        {isMobile && (
          <IconButton
            onClick={handleClose}
            sx={{ position: "absolute", right: 0, top: 0, color: "text.secondary" }}
          >
            <CloseIcon />
          </IconButton>
        )}
        
        <DialogContent sx={{ py: 3, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
          <Box sx={{ 
            width: 64, 
            height: 64, 
            borderRadius: "50%", 
            backgroundColor: "rgba(76, 198, 110, 0.1)",
            display: "flex", 
            justifyContent: "center", 
            alignItems: "center" 
          }}>
            <LogoutOutlinedIcon sx={{ fontSize: 32, color: "primary.main" }} />
          </Box>

          <Typography variant="h6" sx={{ color: "#FFFFFF", fontWeight: 600 }}>
            Are you sure you want to logout?
          </Typography>
        </DialogContent>

        

        <Box display={'flex'} gap={2}>
          <Button
            fullWidth
            variant="contained"
            onClick={onConfirm}
            disabled={loading}
            startIcon={loading && <CircularProgress size={20} color="inherit" />}
          >
            Logout
          </Button>

          <Button
            fullWidth
            
            onClick={handleClose}
            disabled={loading}
            variant="outlined"
            sx={{ color: "text.secondary", borderColor: "text.secondary" }}
          >
            Cancel
          </Button>
       </Box>
      </Box>
    </Dialog>
  );
};

export default LogoutModal;

