
import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { Box, CircularProgress, Tooltip } from '@mui/material';
import { getSecureFileUrl, mediaSourceNeedsAuthorizedFetch } from '../utils/fileHelpers';
import { fetchSecureMediaBlobUrl } from '../utils/mediaCache';
import ImagePreviewModal from './ImagePreviewModal';

const ImageView = ({
  src,
  alt,
  sx,
  loading: loadingProp = 'lazy',
  previewable = true,
  previewTitle,
  disablePreview = false,
  onClick,
  ...props
}) => {
  const [imageUrl, setImageUrl] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);

  const token = useSelector((state) => state.auth.token);
  const userId = 1;

  const canPreview = previewable && !disablePreview && Boolean(imageUrl) && !error && !loading;

  useEffect(() => {
    let cancelled = false;

    if (!src) {
      setImageUrl('');
      return undefined;
    }

    if (src.startsWith('http://') || src.startsWith('https://') || src.startsWith('blob:') || src.startsWith('data:')) {
      setImageUrl(src);
      return undefined;
    }

    const resolved = getSecureFileUrl(src, userId);
    if (!resolved) {
      setImageUrl('');
      return undefined;
    }
    if (!mediaSourceNeedsAuthorizedFetch(resolved)) {
      setImageUrl(resolved);
      return undefined;
    }

    setLoading(true);
    setError(false);

    fetchSecureMediaBlobUrl(resolved, token)
      .then((objectUrl) => {
        if (!cancelled) {
          setImageUrl(objectUrl);
        }
      })
      .catch((err) => {
        console.error('Error loading secure image:', err);
        if (!cancelled) {
          setError(true);
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [src, userId, token]);

  const handleClick = (event) => {
    if (onClick) {
      onClick(event);
    }

    if (canPreview) {
      event.stopPropagation();
      setPreviewOpen(true);
    }
  };

  if (loading) {
    return (
      <Box sx={{ ...sx, display: 'flex', alignItems: 'center', justifyContent: 'center', bgcolor: 'rgba(0,0,0,0.1)' }}>
        <CircularProgress size={24} />
      </Box>
    );
  }

  const imageSx = {
    ...sx,
    ...(canPreview && {
      cursor: 'pointer',
      transition: 'transform 0.2s ease, opacity 0.2s ease',
      '&:hover': {
        transform: 'scale(1.03)',
        opacity: 0.92,
      },
    }),
  };

  const imageElement = error || !imageUrl ? (
    <Box
      component="img"
      src={src || ''}
      alt={alt}
      sx={imageSx}
      loading={loadingProp}
      onClick={canPreview || onClick ? handleClick : undefined}
      {...props}
    />
  ) : (
    <Box
      component="img"
      src={imageUrl}
      alt={alt}
      sx={imageSx}
      loading={loadingProp}
      onClick={canPreview || onClick ? handleClick : undefined}
      {...props}
    />
  );

  return (
    <>
      {canPreview ? (
        <Tooltip title="Click to view full image" arrow>
          <Box component="span" sx={{ display: 'inline-flex', lineHeight: 0 }}>
            {imageElement}
          </Box>
        </Tooltip>
      ) : (
        imageElement
      )}

      <ImagePreviewModal
        open={previewOpen}
        onClose={() => setPreviewOpen(false)}
        src={src}
        displayUrl={imageUrl}
        alt={alt || previewTitle || 'Image'}
        title={previewTitle || alt || 'Image Preview'}
      />
    </>
  );
};

export default ImageView;
