import React, { useEffect, useState } from "react";
import ClickAwayListener from "@mui/material/ClickAwayListener";
import { Box, Typography, IconButton } from "@mui/material";
import MenuIcon from "@mui/icons-material/Menu";
import MoreVertIcon from "@mui/icons-material/MoreVert";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";
import KeyboardArrowDownIcon from "@mui/icons-material/KeyboardArrowDown";
import PersonOutlineIcon from "@mui/icons-material/PersonOutline";
import VpnKeyOutlinedIcon from "@mui/icons-material/VpnKeyOutlined";
import LogoutOutlinedIcon from "@mui/icons-material/LogoutOutlined";
import LiveClock from "./LiveClock";

import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { logout, setUser } from "../../Redux/Slices/AuthSlice";
import ChangePassword from "../../pages/AdminPages/Dashboard/ChangePassword";
import UpdateProfile from "../../pages/AdminPages/Dashboard/UpdateProfile";
import LogoutModal from "../LogoutModel";
import { decryptToken } from "../../Utlis/Encryption";
import { toast } from "react-hot-toast";
import NotificationMenu from "./NotificationMenu";
import AvatarView from "../AvatarView";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const DashboardHeader = ({
  isMobile,
  toggleSidebar,
  toggleHeaderMenu,
  showHeaderMenu,
}) => {
  const [showMoreOptions, setShowMoreOptions] = useState(false);
  const [imgError, setImgError] = useState(false);
  const [open, setOpen] = useState(false);
  const [updateProfileOpen, setUpdateProfileOpen] = useState(false);
  const [logoutModalOpen, setLogoutModalOpen] = useState(false);
  const [isLoggingOut, setIsLoggingOut] = useState(false);

  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { user, token } = useSelector((state) => state.auth);

  const getProfileImageSrc = (raw) => {
    if (!raw) return null;
    if (raw.startsWith("data:")) return raw;
    if (/^https?:\/\//i.test(raw)) return raw;
    const prefix = raw.startsWith("/") ? "" : "/";
    return `${BASE_URL}${prefix}${raw}`;
  };

  const handleLogoutConfirm = async () => {
    try {
      setIsLoggingOut(true);
      if (token) {
        await fetch(`${BASE_URL}/auth/logout`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
        });
      }
      toast.success( "Logged out successfully");
    } catch (err) {
      console.error("Logout failed on server:", err);
    } finally {
      setIsLoggingOut(false);
      dispatch(logout());
      setShowMoreOptions(false);
      navigate("/");
      setLogoutModalOpen(false);
    }
  };


  // Get display name and email - use data from Redux auth slice
  const getDisplayName = () => {
    // Show only first name
    if (user?.first_name) return user.first_name;
    if (user?.name) return user.name.split(' ')[0];
    return "Admin";
  };

  const getDisplayEmail = () => {
    return user?.email || "admin@gmail.com";
  };

  const getDisplayImage = () => {
    return getProfileImageSrc(user?.profile_image);
  };

  return (
    <>
      <Box
        sx={{
          height: 70,
          px: 2,
          display: "flex",
          py: isMobile ? 3 : 2,
          alignItems: "center",
          justifyContent: "space-between",
          backgroundColor: "#001e08ff",
          position: "sticky", 
          top: 0,
          zIndex: 1100,
        }}
      >
        {isMobile ? (
          /* ── Mobile layout ─────────────────────────────────────────────── */
          <>
            <Box sx={{ display: "flex", alignItems: "center", gap: { xs: 0.8, sm: 1.5 } }}>
              <IconButton onClick={toggleSidebar} sx={{ p: { xs: 0.5, sm: 1 } }}>
                <MenuIcon sx={{ color: "#FFFFFF" }} />
              </IconButton>
              <Box
                component="img"
                src="/favicon.svg"
                sx={{ width: { xs: 28, sm: 32 }, height: { xs: 28, sm: 32 }, objectFit: "contain", display: { xs: "none", sm: "block" } }}
                alt="Logo"
                onClick={() => navigate("/")}
              />
              <Typography
                sx={{
                  color: "#fff",
                  fontWeight: 800,
                  fontSize: { xs: '0.75rem', sm: '0.85rem' },
                  display: { xs: 'none', sm: 'block' },
                  ml: 0.5
                }}
              >
                Savage Mushroom Fitness
              </Typography>
            </Box>

            <Box sx={{ flex: 1 }} />

            {/* Right: clock + notifications + avatar */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <LiveClock compact />
              <NotificationMenu />
              <IconButton onClick={() => setShowMoreOptions(!showMoreOptions)} sx={{ p: 0.5 }}>
                <AvatarView
                  src={user?.profile_image}
                  alt={user?.name}
                  previewTitle={user?.name}
                  disablePreview
                  sx={{
                    width: 38,
                    height: 38,
                    border: "2px solid rgba(76, 198, 110, 0.3)",
                  }}
                />
              </IconButton>
            </Box>
          </>
        ) : (
           <>
            {/* Left: logo + app name + clock */}
            <Box sx={{ display: "flex", alignItems: "center", gap: 3 }}>
              <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
                <Box
                  component="img"
                  src="/favicon.svg"
                  sx={{ width: 40, height: 40, objectFit: "contain" }}
                  alt="Logo"
                />
                <Typography variant="h6" sx={{ color: "#fff", fontWeight: 700, fontSize: '1rem', letterSpacing: '-0.02em' }}>
                  Savage Mushroom Fitness
                </Typography>
              </Box>
              
              <LiveClock />
            </Box>

            <Box sx={{ flex: 1 }} /> {/* Spacer */}
            <Box sx={{ display: "flex", alignItems: "center", gap: 2.5 }}>
              <NotificationMenu />
              {/* Profile + more */}
              <Box
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 1.5,
                  cursor: "pointer",
                }}
                onClick={() => setShowMoreOptions((prev) => !prev)}
              >
                <AvatarView
                  src={user?.profile_image}
                  alt={user?.name}
                  previewTitle={user?.name}
                  disablePreview
                  sx={{
                    width: 42,
                    height: 42,
                    border: "2px solid rgba(76, 198, 110, 0.3)",
                  }}
                />

                <Box sx={{ display: "flex", flexDirection: "column" }}>
                  <Typography
                    sx={{
                      color: "#FFFFFF",
                      fontSize: "14px",
                      fontWeight: 600,
                      lineHeight: 1.2,
                    }}
                  >
                    {getDisplayName()}
                  </Typography>
                  <Typography
                    sx={{
                      color: "text.secondary",
                      fontSize: "12px",
                      fontWeight: 400,
                    }}
                  >
                    {getDisplayEmail()}
                  </Typography>
                </Box>

                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    width: 20,
                    height: 20,
                    borderRadius: "50%",
                    backgroundColor: "rgba(76, 198, 110, 0.15)",
                  }}
                >
                  <KeyboardArrowDownIcon
                    sx={{
                      color: "#4CC66E",
                      fontSize: "18px",
                      transform: showMoreOptions ? "rotate(180deg)" : "none",
                      transition: "transform 0.2s",
                    }}
                  />
                </Box>
              </Box>
            </Box>
          </>
        )}

        {/* More options dropdown */}
        {showMoreOptions && (
          <ClickAwayListener onClickAway={() => setShowMoreOptions(false)}>
            <Box
              sx={{
                position: "absolute",
                top: 70,
                right: 25,
                width: 190,
                backgroundColor: "#001e08ff",
                border: "1px solid #333333",
                boxShadow: "0 4px 20px rgba(0, 0, 0, 0.5)",
                borderRadius: "8px",
                overflow: "hidden",
                zIndex: 2000,
              }}
            >
              {[
                {
                  label: "Update Profile",
                  icon: PersonOutlineIcon,
                  action: () => {
                    setShowMoreOptions(false);
                    setUpdateProfileOpen(true);
                  },
                },
                {
                  label: "Change Password",
                  icon: VpnKeyOutlinedIcon,
                  action: () => {
                    setShowMoreOptions(false);
                    setOpen(true);
                  },
                },
                {
                  label: "Logout",
                  icon: LogoutOutlinedIcon,
                  action: () => setLogoutModalOpen(true),
                },
              ].map((item, i) => (
                <Box
                  key={i}
                  onClick={item.action}
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 1.5,
                    px: 2,
                    py: 1.2,
                    borderBottom: i < 1 ? "1px solid #333333" : "none",
                    cursor: "pointer",
                    color: "#FFFFFF",
                    transition: "all 0.2s ease",
                    "&:hover": {
                      backgroundColor: "rgba(255, 255, 255, 0.05)",
                      color: "#4CC66E",
                    },
                  }}
                >
                  <item.icon
                    sx={{
                      fontSize: "18px",
                      transition: "color 0.2s ease",
                      color: "inherit",
                    }}
                  />
                  <Typography
                    sx={{
                      fontSize: "13px",
                      fontWeight: 500,
                      color: "inherit",
                      transition: "color 0.2s ease",
                    }}
                  >
                    {item.label}
                  </Typography>
                </Box>
              ))}
            </Box>
          </ClickAwayListener>
        )}

        <UpdateProfile
          open={updateProfileOpen}
          onClose={() => setUpdateProfileOpen(false)}
          user={user}
          token={token}
          onProfileUpdated={(updatedUser) => dispatch(setUser(updatedUser))}
        />
        <ChangePassword open={open} onClose={() => setOpen(false)} />
      </Box>

      <LogoutModal
        open={logoutModalOpen}
        loading={isLoggingOut}
        onClose={() => setLogoutModalOpen(false)}
        onConfirm={handleLogoutConfirm}
      />
    </>
  );
};

export default DashboardHeader;
