import React, { useMemo } from 'react';
import { Box, Typography, Stack } from '@mui/material';
 
const PasswordStrengthBar = ({ password = '' }) => {
  const strength = useMemo(() => {
    let score = 0;
    if (!password) return 0;
    if (password.length >= 8) score += 1;
    if (/[A-Z]/.test(password)) score += 1;
    if (/[a-z]/.test(password)) score += 1;
    if (/[0-9]/.test(password)) score += 1;
    if (/[!@#$%^&*()[\]{}\-_+=~`|:;"'<>,.?/\\]/.test(password)) score += 1;
    return score;
  }, [password]);

  const config = [
    { label: 'Very Weak', color: '#FF4444' },
    { label: 'Weak', color: '#FF4444' },
    { label: 'Fair', color: '#F5A623' },
    { label: 'Good', color: '#5BA4F5' },
    { label: 'Strong', color: '#4CC66E' },
  ];

  const current = strength > 0 ? config[strength - 1] : { label: '', color: 'transparent' };

  return (
    <Box sx={{ mt: 1, mb: 2 }}>
      <Stack direction="row" spacing={1} sx={{ mb: 1 }}>
        {[1, 2, 3, 4, 5].map((s) => (
          <Box
            key={s}
            sx={{
              height: 6,
              flex: 1,
              borderRadius: '4px',
              bgcolor: s <= strength ? current.color : 'rgba(255, 255, 255, 0.08)',
              transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
              boxShadow: s <= strength ? `0 0 12px ${current.color}33` : 'none',
              border: '1px solid rgba(255, 255, 255, 0.05)',
            }}
          />
        ))}
      </Stack>
      {password && (
        <Typography
          variant="caption"
          sx={{
            color: current.color,
            fontWeight: 800,
            textTransform: 'uppercase',
            fontSize: '0.65rem',
            letterSpacing: '0.08em',
            display: 'block',
            transition: 'color 0.3s ease'
          }}
        >
          Password Security: {current.label}
        </Typography>
      )}
    </Box>
  );
};

export default PasswordStrengthBar;
