import { useState, useEffect } from 'react';

const useNetworkStatus = () => {
  const [status, setStatus] = useState({
    isOnline: navigator.onLine,
    effectiveType: navigator.connection ? navigator.connection.effectiveType : 'unknown',
    isSlow: navigator.connection ? (['slow-2g', '2g'].includes(navigator.connection.effectiveType)) : false,
  });

  useEffect(() => {
    const updateOnlineStatus = () => {
      setStatus(prev => ({ ...prev, isOnline: navigator.onLine }));
    };

    const updateConnectionStatus = () => {
      if (navigator.connection) {
        setStatus(prev => ({
          ...prev,
          effectiveType: navigator.connection.effectiveType,
          isSlow: ['slow-2g', '2g'].includes(navigator.connection.effectiveType),
        }));
      }
    };

    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);

    if (navigator.connection) {
      navigator.connection.addEventListener('change', updateConnectionStatus);
    }

    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
      if (navigator.connection) {
        navigator.connection.removeEventListener('change', updateConnectionStatus);
      }
    };
  }, []);

  return status;
};

export default useNetworkStatus;
