import React, { useEffect, useState } from 'react';
import {
  Box,
  CircularProgress,
  Dialog,
  IconButton,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import { Close as CloseIcon } from '@mui/icons-material';
import { useSelector } from 'react-redux';
import { getSecureFileUrl, mediaSourceNeedsAuthorizedFetch } from '../utils/fileHelpers';
import { fetchSecureMediaBlobUrl } from '../utils/mediaCache';

const ImagePreviewModal = ({
  open,
  onClose,
  src,
  displayUrl = '',
  alt = '',
}) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const token = useSelector((state) => state.auth.token);
  const [resolvedUrl, setResolvedUrl] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);

  useEffect(() => {
    if (!open) {
      setResolvedUrl('');
      setLoading(false);
      setError(false);
      return undefined;
    }

    if (displayUrl) {
      setResolvedUrl(displayUrl);
      setLoading(false);
      setError(false);
      return undefined;
    }

    if (!src) {
      setResolvedUrl('');
      setLoading(false);
      setError(true);
      return undefined;
    }

    let cancelled = false;

    if (
      src.startsWith('http://') ||
      src.startsWith('https://') ||
      src.startsWith('blob:') ||
      src.startsWith('data:')
    ) {
      setResolvedUrl(src);
      setLoading(false);
      setError(false);
      return undefined;
    }

    const resolved = getSecureFileUrl(src, 1);
    if (!resolved) {
      setResolvedUrl('');
      setLoading(false);
      setError(true);
      return undefined;
    }

    if (!mediaSourceNeedsAuthorizedFetch(resolved)) {
      setResolvedUrl(resolved);
      setLoading(false);
      setError(false);
      return undefined;
    }

    setLoading(true);
    setError(false);

    fetchSecureMediaBlobUrl(resolved, token)
      .then((objectUrl) => {
        if (!cancelled) {
          setResolvedUrl(objectUrl);
        }
      })
      .catch((err) => {
        console.error('Error loading preview image:', err);
        if (!cancelled) {
          setError(true);
          setResolvedUrl('');
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [open, src, displayUrl, token]);

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth={false}
      scroll="body"
      PaperProps={{
        sx: {
          m: isMobile ? 1.5 : 2,
          p: 0,
          overflow: 'hidden',
          bgcolor: '#000000',
          backgroundImage: 'none',
          borderRadius: isMobile ? '12px' : '14px',
          border: '1px solid rgba(255, 255, 255, 0.1)',
          boxShadow: '0 16px 48px rgba(0, 0, 0, 0.65)',
          width: 'auto',
          maxWidth: 'min(92vw, 340px)',
        },
      }}
      slotProps={{
        backdrop: {
          sx: {
            bgcolor: 'rgba(0, 0, 0, 0.82)',
          },
        },
      }}
    >
      <Box
        sx={{
          position: 'relative',
          lineHeight: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          minWidth: loading || error ? 160 : 'auto',
          minHeight: loading || error ? 160 : 'auto',
        }}
      >
        <IconButton
          aria-label="Close image preview"
          onClick={onClose}
          size="small"
          sx={{
            position: 'absolute',
            top: 6,
            right: 6,
            zIndex: 2,
            color: '#FFFFFF',
            bgcolor: 'rgba(0, 0, 0, 0.55)',
            backdropFilter: 'blur(4px)',
            width: 28,
            height: 28,
            '&:hover': {
              bgcolor: 'rgba(0, 0, 0, 0.75)',
            },
          }}
        >
          <CloseIcon sx={{ fontSize: 16 }} />
        </IconButton>

        {loading ? (
          <Box
            sx={{
              width: 160,
              height: 160,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              bgcolor: '#001e08',
            }}
          >
            <CircularProgress size={32} sx={{ color: '#4CC66E' }} />
          </Box>
        ) : error || !resolvedUrl ? (
          <Box
            sx={{
              width: 160,
              height: 160,
              bgcolor: '#001e08',
            }}
          />
        ) : (
          <Box
            component="img"
            src={resolvedUrl}
            alt={alt}
            sx={{
              display: 'block',
              width: 'auto',
              height: 'auto',
              maxWidth: 'min(92vw, 340px)',
              maxHeight: 'min(78vh, 460px)',
              objectFit: 'contain',
              verticalAlign: 'top',
            }}
          />
        )}
      </Box>
    </Dialog>
  );
};

export default ImagePreviewModal;
