import React, { useEffect, useState } from "react";
import { Box, Typography, Button, TextField, CircularProgress } from "@mui/material";
import { useFormik } from "formik";
import BaseModal from "../../../components/BaseModal";
import FileUpload from "../../../components/FileUpload";
import { toast } from "react-hot-toast";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const UpdateProfile = ({ open, onClose, user = {}, token, onProfileUpdated }) => {
  const [isSaving, setIsSaving] = useState(false);
  const [profileImageUrl, setProfileImageUrl] = useState(user?.profile_image || "");

  const getInitialName = () => user?.name?.trim() || "";

  useEffect(() => {
    if (open) {
      setProfileImageUrl(user?.profile_image || "");
      formik.resetForm();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, user]);

  const formik = useFormik({
    enableReinitialize: true,
    initialValues: {
      name: getInitialName(),
      email: user?.email || "",
    },
    validate: (values) => {
      const errors = {};
      if (!values.name?.trim()) {
        errors.name = "Name is required";
      }
      if (!values.email?.trim()) {
        errors.email = "Email is required";
      } else if (!EMAIL_REGEX.test(values.email.trim())) {
        errors.email = "Enter a valid email address";
      }
      return errors;
    },
    onSubmit: async (values) => {
      if (!token) {
        toast.error("Unable to update profile. Please log in again.");
        return;
      }

      setIsSaving(true);

      try {
        const response = await fetch(`${BASE_URL}/users/${user.id}`, {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            name: values.name.trim(),
            email: values.email.trim(),
            profile_image: profileImageUrl || null,
          }),
        });

        const result = await response.json();

        if (response.ok && !result.error) {
          const updatedUser = {
            ...user,
            ...(result.data?.user || {}), // Backend nests the updated user under data.user
            name: values.name.trim(),
            email: values.email.trim(),
            profile_image: profileImageUrl || user?.profile_image || "",
          };

          onProfileUpdated?.(updatedUser);
          toast.success(result.message || "Profile updated successfully");
          onClose();
        } else {
          toast.error(result.message || "Failed to update profile");
        }
      } catch (error) {
        console.error("Update profile save error:", error);
        toast.error("An error occurred while updating profile");
      } finally {
        setIsSaving(false);
      }
    },
  });

  return (
    <BaseModal
      open={open}
      onClose={onClose}
      title="Update Profile"
      actions={
        <Box sx={{ display: "flex", gap: 2, width: "100%", justifyContent: "flex-end", flexWrap: "wrap", mt: { xs: 2, sm: 0 } }}>
          <Button
            variant="outlined"
            onClick={onClose}
            disabled={isSaving}
            sx={{ color: "text.secondary", borderColor: "rgba(255, 255, 255, 0.15)" }}
          >
            Cancel
          </Button>
          <Button
            variant="contained"
            type="submit"
            form="profile-settings-form"
            disabled={isSaving}
            startIcon={isSaving && <CircularProgress size={18} color="inherit" />}
          >
            Save Changes
          </Button>
        </Box>
      }
      maxWidth="sm"
    >
      <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
       

        <Box sx={{ display: "flex", justifyContent: "center", mt: 1 }}>
          <FileUpload
            folderName="profile_images"
            maxFiles={1}
            accept={{ "image/*": [] }}
            helperText="Drop or choose an image for your profile"
            existingImageUrl={profileImageUrl}
            onUploadSuccess={(url) => setProfileImageUrl(url)}
            onRemove={() => setProfileImageUrl("")}
            shape="circle"
            maxSizeMB={5}
          />
        </Box>

        <Box component="form" id="profile-settings-form" onSubmit={formik.handleSubmit} sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
          <TextField
            fullWidth
            label="Full Name"
            name="name"
            value={formik.values.name}
            onChange={formik.handleChange}
            onBlur={formik.handleBlur}
            error={formik.touched.name && Boolean(formik.errors.name)}
            helperText={formik.touched.name && formik.errors.name}
            InputLabelProps={{ style: { color: "#B0B3B8" } }}
            sx={{
              input: { color: "#FFFFFF" },
              '& .MuiOutlinedInput-root': {
                '& fieldset': { borderColor: 'rgba(255,255,255,0.15)' },
                '&:hover fieldset': { borderColor: 'rgba(76,198,110,0.5)' },
                '&.Mui-focused fieldset': { borderColor: '#4CC66E' },
              },
            }}
          />

          <TextField
            fullWidth
            label="Email"
            name="email"
            type="email"
            value={formik.values.email}
            onChange={formik.handleChange}
            onBlur={formik.handleBlur}
            error={formik.touched.email && Boolean(formik.errors.email)}
            helperText={formik.touched.email && formik.errors.email}
            InputLabelProps={{ style: { color: "#B0B3B8" } }}
            sx={{
              input: { color: "#FFFFFF" },
              '& .MuiOutlinedInput-root': {
                '& fieldset': { borderColor: 'rgba(255,255,255,0.15)' },
                '&:hover fieldset': { borderColor: 'rgba(76,198,110,0.5)' },
                '&.Mui-focused fieldset': { borderColor: '#4CC66E' },
              },
            }}
          />
        </Box>
      </Box>
    </BaseModal>
  );
};

export default UpdateProfile;
