import React, { useState, useEffect, memo } from 'react';
import { Box, Typography } from '@mui/material';
import AccessTimeIcon from '@mui/icons-material/AccessTime';

const USER_LOCALE = navigator.language || 'en-US';
const USER_TIMEZONE = Intl.DateTimeFormat().resolvedOptions().timeZone;

const LiveClock = memo(({ compact = false }) => {
  const [now, setNow] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const timeStr = now.toLocaleTimeString(USER_LOCALE, {
    timeZone: USER_TIMEZONE,
    hour: '2-digit',
    minute: '2-digit',
    second: compact ? undefined : '2-digit',
    hour12: true,
  });

  const dateStr = now.toLocaleDateString(USER_LOCALE, {
    timeZone: USER_TIMEZONE,
    weekday: compact ? undefined : 'short',
    day: 'numeric',
    month: 'short',
    year: compact ? undefined : 'numeric',
  });

  if (compact) {
    return (
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          gap: 1,
          px: 1.2,
          py: 0.5,
          borderRadius: '8px',
          bgcolor: 'rgba(76,198,110,0.06)',
          border: '1px solid rgba(76,198,110,0.15)',
        }}
      >
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            lineHeight: 1.1,
          }}
        >
          <Typography
            sx={{
              color: '#FFFFFF',
              fontSize: '0.65rem',
              fontWeight: 700,
              fontFamily: "'Montserrat', sans-serif",
            }}
          >
            {timeStr}
          </Typography>
          <Typography
            sx={{
              color: 'rgba(255,255,255,0.5)',
              fontSize: '0.5rem',
              fontWeight: 600,
              fontFamily: "'Montserrat', sans-serif",
              textTransform: 'uppercase',
            }}
          >
            {dateStr}
          </Typography>
        </Box>
      </Box>
    );
  }

  return (
    <Box
      sx={{
        display: 'flex',
        alignItems: 'center',
        gap: 1,
        px: 1.5,
        py: 0.6,
        borderRadius: '10px',
        bgcolor: 'rgba(76,198,110,0.06)',
        border: '1px solid rgba(76,198,110,0.15)',
      }}
    >
      <Box sx={{ display: 'flex', flexDirection: 'column', lineHeight: 1 }}>
        <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 0.6 }}>
          <Typography
            sx={{
              color: '#FFFFFF',
              fontSize: '0.82rem',
              fontWeight: 700,
              fontFamily: "'Montserrat', sans-serif",
              letterSpacing: '0.02em',
              lineHeight: 1.2,
            }}
          >
            {timeStr}
          </Typography>
        </Box>

        <Typography
          sx={{
            color: 'rgba(255,255,255,0.4)',
            fontSize: '0.65rem',
            fontWeight: 500,
            fontFamily: "'Montserrat', sans-serif",
            lineHeight: 1.3,
          }}
        >
          {dateStr}
        </Typography>
      </Box>
    </Box>
  );
});

LiveClock.displayName = 'LiveClock';

export default LiveClock;
