






import React, { useState, useCallback } from 'react';
import { Outlet } from 'react-router-dom';
import Sidebar from '../components/Sidebar';
import DashboardHeader from '../components/Headers/DashboardHeader';
import BreadcrumbsTrail from '../components/BreadcrumbsTrail';
import { Box, useMediaQuery, Drawer } from '@mui/material';
const HEADER_HEIGHT = 64;
const SIDEBAR_WIDTH = 270;

const DashboardLayout = () => {
  const [openSidebar, setOpenSidebar] = useState(false);
  const [openHeaderMenu, setOpenHeaderMenu] = useState(false);
  const isMobile = useMediaQuery('(max-width:768px)');

  const toggleSidebar = useCallback(() => setOpenSidebar(true), []);
  const toggleHeaderMenu = useCallback(() => setOpenHeaderMenu((prev) => !prev), []);
  const closeSidebar = useCallback(() => setOpenSidebar(false), []);

  return (
    <Box
      sx={{
        display: 'grid',
        gridTemplateColumns: isMobile ? '1fr' : `${SIDEBAR_WIDTH}px 1fr`,
        gridTemplateRows: `${HEADER_HEIGHT}px 1fr`,
        height: '100vh',
        width: '100vw',
        maxWidth: '100vw',
        overflow: 'hidden',
        backgroundColor: '#000',
      }}
    >
      {/* Header (Full Width) */}
      <Box
        sx={{
          gridColumn: isMobile ? '1 / 2' : '1 / 3',
          gridRow: '1 / 2',
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100%',
          zIndex: 1300, 
          backgroundColor: '#000',
          borderBottom: '1px solid #474747ff',
        }}
      >
        <DashboardHeader
          isMobile={isMobile}
          toggleSidebar={toggleSidebar}
          toggleHeaderMenu={toggleHeaderMenu}
          showHeaderMenu={openHeaderMenu}
        />
      </Box>

      
      {!isMobile && (
        <Box
          sx={{
            gridRow: '2 / 3',
            gridColumn: '1 / 2',
            borderRight: '1px solid #474747ff',
            backgroundColor: '#000',
            zIndex: 1200,
            overflowY: 'auto',
            overflowX: 'hidden',
          }}
        >
          <Sidebar />
        </Box>
      )}

      
      {isMobile && (
        <Drawer
          anchor="left"
          open={openSidebar}
          onClose={closeSidebar}
        >
          <Sidebar mobile onClose={closeSidebar} />
        </Drawer>
      )}

      
      <Box
        sx={{
          gridColumn: isMobile ? '1 / 2' : '2 / 3',
          gridRow: '2 / 3',
          overflowY: 'auto',
          backgroundColor: '#000000ff',
          px: isMobile ? 0.5 : 1.5,
          py: 2,
        }}
      >
        <BreadcrumbsTrail />
        <Outlet />
      </Box>
    </Box>
  );
};

export default DashboardLayout;




