import React, { useEffect, useState, useMemo } from "react";
import {
  Box,
  useMediaQuery,
  useTheme,
  CircularProgress,
  Dialog,
  Slide,
  Typography,
  IconButton,
  Button,
  TextField,
  InputAdornment
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';
import { useFormik } from "formik";
import PasswordStrengthBar from "../../../components/PasswordStrengthBar";
import { toast } from "react-hot-toast";
import { useSelector } from "react-redux";

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const BASE_URL = process.env.REACT_APP_API_BASE_URL;


const ChangePassword = ({ open, onClose }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const [isLoading, setIsLoading] = useState(false);
  const [showCurrentPwd, setShowCurrentPwd] = useState(false);
  const [showNewPwd, setShowNewPwd] = useState(false);
  const [showConfirmPwd, setShowConfirmPwd] = useState(false);
  
  const token = useSelector((state) => state.auth.token);


  useEffect(() => {
    if (open) {
      formik.resetForm();
    }
  }, [open]);

  const formik = useFormik({
    initialValues: {
      currentPassword: "",
      newPassword: "",
      confirmPassword: "",
    },
    validate: (values) => {
      const errors = {};
      const pwd = values.newPassword || "";

      if (!values.currentPassword)
        errors.currentPassword = "Current password is required";

      if (!pwd) {
        errors.newPassword = "New password is required";
      } else {
        const hasLen = pwd.length >= 8;
        const hasLower = /[a-z]/.test(pwd);
        const hasUpper = /[A-Z]/.test(pwd);
        const hasNum = /[0-9]/.test(pwd);
        const hasSpecial = /[!@#$%^&*()[\]{}\-_+=~`|:;"'<>,.?/\\]/.test(pwd);

        if (!(hasLen && hasLower && hasUpper && hasNum && hasSpecial)) {
          errors.newPassword = "Password must meet all complexity requirements";
        }
      }

      if (!values.confirmPassword)
        errors.confirmPassword = "Please confirm your new password";
      else if (values.confirmPassword !== values.newPassword)
        errors.confirmPassword = "Passwords do not match";

      return errors;
    },
    onSubmit: async (values) => {
      try {
        if (values.currentPassword === values.newPassword) {
          toast.error("New password must be different from current password");
          return;
        }

        setIsLoading(true);

        const response = await fetch(`${BASE_URL}/auth/change-password`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            currentPassword: values.currentPassword,
            newPassword: values.newPassword,
          }),
        });

        const data = await response.json();

        if (response.ok && !data.error) {
          toast.success(data.message || "Password changed successfully");
          setTimeout(() => onClose(), 1000);
        } else {
          toast.error(data.message || "Failed to change password");
        }
      } catch (error) {
        console.error("🚨 Change password error:", error);
        toast.error("An error occurred while changing password");
      } finally {
        setIsLoading(false);
      }
    },
  });

  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullScreen={isMobile}
      TransitionComponent={isMobile ? Transition : undefined}
      PaperProps={{
        sx: {
          backgroundColor: "#1A1A1A",
          backgroundImage: "none",
          borderRadius: isMobile ? 0 : "12px",
          border: isMobile ? "none" : "1px solid rgba(255, 255, 255, 0.1)",
          boxShadow: "0 8px 32px rgba(0,0,0,0.5)",
          width: "100%",
          maxWidth: 450,
          m: isMobile ? 0 : 2,
        }
      }}
    >
      <Box sx={{ p: { xs: 3, sm: 4 }, position: 'relative' }}>
        <IconButton 
          onClick={onClose} 
          sx={{ position: 'absolute', right: 16, top: 16, color: 'text.secondary' }}
        >
          <CloseIcon />
        </IconButton>

        <Box sx={{ mb: 3 }}>
          <Typography variant="h5" sx={{ color: "#FFFFFF", mb: 0.5 }}>
            Change Password
          </Typography>
          <Typography variant="body2" sx={{ color: "text.secondary" }}>
            Secure your account by choosing a strong password.
          </Typography>
        </Box>

        <form onSubmit={formik.handleSubmit}>
          <Box sx={{ display: "flex", flexDirection: "column", gap: 2.5 }}>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              <Typography variant="body2" sx={{ color: "#FFFFFF" }}>
                Current Password
              </Typography>
              <TextField
                fullWidth
                name="currentPassword"
                type={showCurrentPwd ? 'text' : 'password'}
                placeholder="*********"
                value={formik.values.currentPassword}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={formik.touched.currentPassword && Boolean(formik.errors.currentPassword)}
                helperText={formik.touched.currentPassword && formik.errors.currentPassword}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton onClick={() => setShowCurrentPwd(!showCurrentPwd)} edge="end" sx={{ color: 'text.secondary' }}>
                        {showCurrentPwd ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            </Box>

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              <Typography variant="body2" sx={{ color: "#FFFFFF" }}>
                New Password
              </Typography>
              <TextField
                fullWidth
                name="newPassword"
                type={showNewPwd ? 'text' : 'password'}
                placeholder="*********"
                value={formik.values.newPassword}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={formik.touched.newPassword && Boolean(formik.errors.newPassword)}
                helperText={formik.touched.newPassword && formik.errors.newPassword}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton onClick={() => setShowNewPwd(!showNewPwd)} edge="end" sx={{ color: 'text.secondary' }}>
                        {showNewPwd ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            </Box>

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
              <Typography variant="body2" sx={{ color: "#FFFFFF" }}>
                Confirm New Password
              </Typography>
              <TextField
                fullWidth
                name="confirmPassword"
                type={showConfirmPwd ? 'text' : 'password'}
                placeholder="*********"
                value={formik.values.confirmPassword}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={formik.touched.confirmPassword && Boolean(formik.errors.confirmPassword)}
                helperText={formik.touched.confirmPassword && formik.errors.confirmPassword}
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton onClick={() => setShowConfirmPwd(!showConfirmPwd)} edge="end" sx={{ color: 'text.secondary' }}>
                        {showConfirmPwd ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            </Box>

            <PasswordStrengthBar
              password={formik.values.newPassword}
            />

            <Box sx={{ display: "flex", gap: 2, mt: 1 }}>
              <Button
                fullWidth
                variant="outlined"
                onClick={onClose}
                disabled={isLoading}
                sx={{ color: "text.secondary", borderColor: "rgba(255, 255, 255, 0.1)" }}
              >
                Cancel
              </Button>
              <Button
                fullWidth
                variant="contained"
                type="submit"
                disabled={isLoading}
                startIcon={isLoading && <CircularProgress size={20} color="inherit" />}
              >
                Update
              </Button>
            </Box>
          </Box>
        </form>
      </Box>
    </Dialog>
  );
};

export default ChangePassword;

