const FILE_PUBLIC_ORIGIN =
    process.env.REACT_APP_FILE_PUBLIC_ORIGIN || 'https://fitness-link.mtechub.org';

/** Full URL for multipart plain upload (FormData field name: `file`). */
export const UPLOAD_PLAIN_URL =
    process.env.REACT_APP_UPLOAD_PLAIN_URL ||
    'https://fitness-link.mtechub.org/api/upload-plain';

/**
 * Optional: old host that served `/api/encrypted-view/:id` for records still storing bare file ids.
 * If unset, bare ids are resolved as public paths under FILE_PUBLIC_ORIGIN.
 */
const LEGACY_ENCRYPTED_UPLOAD_BASE = process.env.REACT_APP_LEGACY_ENCRYPTED_UPLOAD_BASE || '';

/**
 * Resolves a stored media reference to a browser-usable URL.
 * Prefer storing full https URLs from upload-plain; no view API is constructed unless legacy base is set.
 */
export const getSecureFileUrl = (pathOrId, userId) => {
    if (!pathOrId) return '';
    if (typeof pathOrId !== 'string') return '';

    const t = pathOrId.trim();
    if (!t) return '';

    if (t.startsWith('http://') || t.startsWith('https://') || t.startsWith('blob:') || t.startsWith('data:')) {
        return t;
    }

    if (t.startsWith('/')) {
        const base = FILE_PUBLIC_ORIGIN.endsWith('/') ? FILE_PUBLIC_ORIGIN : `${FILE_PUBLIC_ORIGIN}/`;
        return new URL(t.replace(/^\//, ''), base).toString();
    }

    if (LEGACY_ENCRYPTED_UPLOAD_BASE) {
        const base = LEGACY_ENCRYPTED_UPLOAD_BASE.replace(/\/$/, '');
        const url = `${base}/api/encrypted-view/${encodeURIComponent(t)}`;
        return userId != null && userId !== '' ? `${url}?user_id=${encodeURIComponent(userId)}` : url;
    }

    const origin = FILE_PUBLIC_ORIGIN.replace(/\/$/, '');
    return `${origin}/${t.replace(/^\//, '')}`;
};

/** True when the URL must be fetched with Authorization and shown via blob (legacy encrypted view). */
export const mediaSourceNeedsAuthorizedFetch = (resolvedUrl) => {
    if (!resolvedUrl || typeof resolvedUrl !== 'string') return false;
    return resolvedUrl.includes('/api/encrypted-view/');
};

const trimStr = (v) => (typeof v === 'string' && v.trim() ? v.trim() : '');

/**
 * URL to persist after upload-plain (same shape you send to the backend as before: one string field).
 * Prefer Storj gateway presigned URL; fall back to absolute paths on the API host.
 */
export const extractUploadedFileUrl = (result) => {
    if (!result || typeof result !== 'object') return '';

    const candidates = [
        result.gateway_presigned_url,
        result.url,
        result.file_url,
        result.secure_url,
        result.location,
        typeof result.data === 'string' ? result.data : result.data?.url,
        typeof result.file === 'string' ? result.file : result.file?.url,
        result.path,
    ];
    for (const c of candidates) {
        const s = trimStr(c);
        if (s) return s;
    }

    const rel = trimStr(result.view_url) || trimStr(result.download_url);
    if (!rel) return '';

    if (rel.startsWith('http://') || rel.startsWith('https://')) return rel;

    const origin = FILE_PUBLIC_ORIGIN.replace(/\/$/, '');
    if (rel.startsWith('/')) return `${origin}${rel}`;
    return `${origin}/${rel}`;
};
