import { createContext, useCallback, useContext, useMemo, useState } from 'react';

const SIGNUP_KEY = 'signupData';
const PLAN_KEY = 'selectedPlan';
const PLAN_LABEL_KEY = 'selectedPlanLabel';
const ENTRY_FLOW_KEY = 'entryFlow';

const readJson = (key) => {
  try {
    const raw = sessionStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
};

const SignupContext = createContext(null);

export const SignupProvider = ({ children }) => {
  const [signupData, setSignupDataState] = useState(() => readJson(SIGNUP_KEY));
  const [selectedPlan, setSelectedPlanState] = useState(() => readJson(PLAN_KEY));
  const [subscription, setSubscription] = useState(null);
  const [entryFlow, setEntryFlowState] = useState(() => {
    try {
      return sessionStorage.getItem(ENTRY_FLOW_KEY) || 'signup-first';
    } catch {
      return 'signup-first';
    }
  });

  const setSignupData = useCallback((data) => {
    setSignupDataState(data);
    if (data) {
      sessionStorage.setItem(SIGNUP_KEY, JSON.stringify(data));
    } else {
      sessionStorage.removeItem(SIGNUP_KEY);
    }
  }, []);

  const clearSignupData = useCallback(() => {
    setSignupDataState(null);
    sessionStorage.removeItem(SIGNUP_KEY);
  }, []);

  const setSelectedPlan = useCallback((plan) => {
    setSelectedPlanState(plan);
    if (plan) {
      sessionStorage.setItem(PLAN_KEY, JSON.stringify(plan));
    } else {
      sessionStorage.removeItem(PLAN_KEY);
    }
  }, []);

  const setPlanLabel = useCallback((label) => {
    try {
      if (label) sessionStorage.setItem(PLAN_LABEL_KEY, label);
      else sessionStorage.removeItem(PLAN_LABEL_KEY);
    } catch {
      // non-fatal
    }
  }, []);

  const getPlanLabel = useCallback(() => {
    try {
      return sessionStorage.getItem(PLAN_LABEL_KEY) || '';
    } catch {
      return '';
    }
  }, []);

  const clearSelectedPlan = useCallback(() => {
    setSelectedPlanState(null);
    sessionStorage.removeItem(PLAN_KEY);
    sessionStorage.removeItem(PLAN_LABEL_KEY);
  }, []);

  const setEntryFlow = useCallback((flow) => {
    setEntryFlowState(flow);
    try {
      sessionStorage.setItem(ENTRY_FLOW_KEY, flow);
    } catch {
      // non-fatal
    }
  }, []);

  const startSignupFirstFlow = useCallback(() => {
    clearSelectedPlan();
    setEntryFlow('signup-first');
  }, [clearSelectedPlan, setEntryFlow]);

  const startPlanFirstFlow = useCallback(
    (plan) => {
      setEntryFlow('plan-first');
      setSelectedPlan(plan);
    },
    [setEntryFlow, setSelectedPlan],
  );

  const value = useMemo(
    () => ({
      signupData,
      setSignupData,
      clearSignupData,
      selectedPlan,
      setSelectedPlan,
      clearSelectedPlan,
      setPlanLabel,
      getPlanLabel,
      subscription,
      setSubscription,
      entryFlow,
      setEntryFlow,
      startSignupFirstFlow,
      startPlanFirstFlow,
    }),
    [
      signupData,
      setSignupData,
      clearSignupData,
      selectedPlan,
      setSelectedPlan,
      clearSelectedPlan,
      setPlanLabel,
      getPlanLabel,
      subscription,
      entryFlow,
      setEntryFlow,
      startSignupFirstFlow,
      startPlanFirstFlow,
    ],
  );

  return <SignupContext.Provider value={value}>{children}</SignupContext.Provider>;
};

export const useSignup = () => {
  const ctx = useContext(SignupContext);
  if (!ctx) throw new Error('useSignup must be used within SignupProvider');
  return ctx;
};

export const completionKey = (sessionId) => `payment_success_${sessionId}`;
