import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import { jwtDecode } from "jwt-decode";
import { requestForToken } from "../../firebase";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

// ✅ Async Thunk for Login
export const loginAdmin = createAsyncThunk(
  "auth/loginAdmin",
  async ({ email, password, rememberMe }, { rejectWithValue }) => {
    try {
      const response = await fetch(`${BASE_URL}/auth/admin/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.toLowerCase(), password }),
      });

      const result = await response.json();

      if (!response.ok || result.error) {
        return rejectWithValue(result.message || "Login failed");
      }

      const { user, token, profile_completion_percentage } = result.data;

      const normalizedNameParts = user?.name?.trim().split(/\s+/) || [];
      const normalizedUser = {
        ...user,
        first_name: user?.first_name?.trim() || normalizedNameParts[0] || "",
        last_name: user?.last_name?.trim() || normalizedNameParts.slice(1).join(" ") || "",
      };

      // Handle FCM Token registration
      try {
        const fcmToken = await requestForToken();
        if (fcmToken) {
          const getDeviceId = () => {
            try {
              const existing = localStorage.getItem("device_id");
              if (existing) return existing;
              const newId = (typeof crypto !== "undefined" && crypto.randomUUID)
                ? crypto.randomUUID()
                : `web-${Math.random().toString(36).slice(2, 10)}`;
              localStorage.setItem("device_id", newId);
              return newId;
            } catch (e) {
              return `web-${Math.random().toString(36).slice(2, 10)}`;
            }
          };

          const detectDeviceType = () => {
            try {
              const ua = navigator?.userAgent || "";
              if (/android/i.test(ua)) return "android";
              if (/iphone|ipad|ipod/i.test(ua)) return "ios";
              return "web";
            } catch (e) {
              return "web";
            }
          };

          const payload = {
            fcmToken,
            device_type: detectDeviceType(),
            device_id: getDeviceId(),
          };

          await fetch(`${BASE_URL}/notifications/update-token`, {
            method: "PATCH",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${token}`,
            },
            body: JSON.stringify(payload),
          });
          console.log("FCM token registered successfully.");
        }
      } catch (fcmError) {
        console.error("Failed to register FCM token:", fcmError);
      }

      // Remember Me  only adminCredentials use localStorage
      if (rememberMe) {
        localStorage.setItem("adminCredentials", JSON.stringify({ email, password }));
      } else {
        localStorage.removeItem("adminCredentials");
      }

      let expirationTime = null;
      try {
        const decoded = jwtDecode(token);
        if (decoded.exp) {
          expirationTime = decoded.exp * 1000;
        }
      } catch (e) {
        console.error("Token decode error:", e);
      }

      // Persist auth session to sessionStorage (survives refresh, clears on tab close)
      sessionStorage.setItem("token", token);
      sessionStorage.setItem("user", JSON.stringify(normalizedUser));
      if (expirationTime)
        sessionStorage.setItem("expirationTime", expirationTime.toString());

      return {
        token,
        user: normalizedUser,
        profileCompletion: profile_completion_percentage,
        expirationTime,
      };
    } catch (error) {
      return rejectWithValue(error.message || "Something went wrong");
    }
  },
);

const initialState = {
  token: null,
  user: null,
  expirationTime: null,
  profileCompletion: null,
  otpData: null,
  inviteEmail: null,
  resetToken: null,
  profileUpdateToken: null,
  inviteProfileUpdateToken: null,
  registrationData: null,
  signupData: null,
  selectedPlan: null,
  subscription: null,
  loading: false,
  error: null,
};

// Rehydrate Redux from sessionStorage on page refresh
const loadInitialState = () => {
  try {
    const token = sessionStorage.getItem("token");
    const rawUser = sessionStorage.getItem("user");
    const rawExp = sessionStorage.getItem("expirationTime");

    const parsedUser = rawUser ? JSON.parse(rawUser) : null;
    const expirationTime = rawExp ? parseInt(rawExp, 10) : null;

    const user = parsedUser
      ? {
          ...parsedUser,
          first_name: parsedUser?.first_name?.trim() || (parsedUser?.name?.trim().split(/\s+/)[0] || ""),
          last_name: parsedUser?.last_name?.trim() || (parsedUser?.name?.trim().split(/\s+/).slice(1).join(" ") || ""),
        }
      : null;

    // If token has expired, wipe sessionStorage and start fresh
    if (expirationTime && Date.now() > expirationTime) {
      sessionStorage.removeItem("token");
      sessionStorage.removeItem("user");
      sessionStorage.removeItem("expirationTime");
      return { ...initialState };
    }

    // Rehydrate pre-registration flow data (survives Stripe redirect)
    let signupData = null;
    let selectedPlan = null;
    try {
      const rawSignup = sessionStorage.getItem("signupData");
      const rawPlan = sessionStorage.getItem("selectedPlan");
      signupData = rawSignup ? JSON.parse(rawSignup) : null;
      selectedPlan = rawPlan ? JSON.parse(rawPlan) : null;
    } catch (e) {
      signupData = null;
      selectedPlan = null;
    }

    if (token && user) {
      return { ...initialState, token, user, expirationTime, signupData, selectedPlan };
    }

    return { ...initialState, signupData, selectedPlan };
  } catch (e) {
    console.error("[AuthSlice] Failed to load session:", e);
    return { ...initialState };
  }
};

const authSlice = createSlice({
  name: "auth",
  initialState: loadInitialState(),
  reducers: {
    setOtpData: (state, action) => {
      state.otpData = action.payload;
    },
    setRegistrationData: (state, action) => {
      state.registrationData = action.payload;
    },
    setSignupData: (state, action) => {
      state.signupData = action.payload;
      try {
        sessionStorage.setItem("signupData", JSON.stringify(action.payload));
      } catch (e) {
        console.error("Failed to persist signupData:", e);
      }
    },
    clearSignupData: (state) => {
      state.signupData = null;
      sessionStorage.removeItem("signupData");
    },
    setSelectedPlan: (state, action) => {
      state.selectedPlan = action.payload;
      try {
        sessionStorage.setItem("selectedPlan", JSON.stringify(action.payload));
      } catch (e) {
        console.error("Failed to persist selectedPlan:", e);
      }
    },
    clearSelectedPlan: (state) => {
      state.selectedPlan = null;
      sessionStorage.removeItem("selectedPlan");
    },
    setSubscription: (state, action) => {
      state.subscription = action.payload;
    },
    setResetToken: (state, action) => {
      state.resetToken = action.payload;
    },
    setProfileUpdateToken: (state, action) => {
      state.profileUpdateToken = action.payload;
    },
    setInviteProfileUpdateToken: (state, action) => {
      state.inviteProfileUpdateToken = action.payload;
    },
    setInviteEmail: (state, action) => {
      state.inviteEmail = action.payload;
    },
    setUser: (state, action) => {
      const payload = action.payload || {};
      const nameParts = payload?.name?.trim().split(/\s+/) || [];
      state.user = {
        ...payload,
        first_name: payload?.first_name?.trim() || nameParts[0] || "",
        last_name: payload?.last_name?.trim() || nameParts.slice(1).join(" ") || "",
      };
      try {
        sessionStorage.setItem("user", JSON.stringify(state.user));
      } catch (error) {
        console.error("Failed to update user in session storage:", error);
      }
    },
    logout: (state) => {
      // Reset Redux state and wipe sessionStorage auth session
      Object.assign(state, initialState);
      sessionStorage.removeItem("token");
      sessionStorage.removeItem("user");
      sessionStorage.removeItem("expirationTime");
      sessionStorage.removeItem("signupData");
      sessionStorage.removeItem("selectedPlan");
      // Keep adminCredentials in localStorage only if Remember Me was used
      console.log("🔐 [AuthSlice] Logout called. Session cleared.");
    },
    clearError: (state) => {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(loginAdmin.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(loginAdmin.fulfilled, (state, action) => {
        state.loading = false;
        state.token = action.payload.token;
        state.user = action.payload.user;
        state.profileCompletion = action.payload.profileCompletion;
        state.expirationTime = action.payload.expirationTime;
      })
      .addCase(loginAdmin.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload;
      });
  },
});

export const {
  setOtpData,
  logout,
  setResetToken,
  setProfileUpdateToken,
  setInviteEmail,
  setInviteProfileUpdateToken,
  setUser,
  setRegistrationData,
  setSignupData,
  clearSignupData,
  setSelectedPlan,
  clearSelectedPlan,
  setSubscription,
  clearError,
} = authSlice.actions;

export default authSlice.reducer;
