
import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { Box, CircularProgress } from '@mui/material';
import { getSecureFileUrl, mediaSourceNeedsAuthorizedFetch } from '../utils/fileHelpers';
import { fetchSecureMediaBlobUrl } from '../utils/mediaCache';

const loadSecureMedia = (source, userId, token, setUrl, setLoading, setError) => {
    if (!source) {
        setUrl('');
        return undefined;
    }

    if (source.startsWith('http://') || source.startsWith('https://') || source.startsWith('blob:') || source.startsWith('data:')) {
        setUrl(source);
        return undefined;
    }

    const resolved = getSecureFileUrl(source, userId);
    if (!resolved) {
        setUrl('');
        return undefined;
    }
    if (!mediaSourceNeedsAuthorizedFetch(resolved)) {
        setUrl(resolved);
        return undefined;
    }

    let cancelled = false;
    setLoading(true);
    setError(false);

    fetchSecureMediaBlobUrl(resolved, token)
        .then((objectUrl) => {
            if (!cancelled) {
                setUrl(objectUrl);
            }
        })
        .catch((err) => {
            console.error('Error loading secure media:', err);
            if (!cancelled) {
                setError(true);
            }
        })
        .finally(() => {
            if (!cancelled) {
                setLoading(false);
            }
        });

    return () => {
        cancelled = true;
    };
};

const VideoView = ({ src, poster, sx, controls = true, ...props }) => {
    const [videoUrl, setVideoUrl] = useState('');
    const [posterUrl, setPosterUrl] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(false);

    const token = useSelector((state) => state.auth.token);
    const userId = 1;

    useEffect(() => {
        return loadSecureMedia(src, userId, token, setVideoUrl, setLoading, setError);
    }, [src, userId, token]);

    useEffect(() => {
        return loadSecureMedia(
            poster,
            userId,
            token,
            setPosterUrl,
            () => {},
            () => {},
        );
    }, [poster, userId, token]);

    if (loading) {
        return (
            <Box sx={{ ...sx, display: 'flex', alignItems: 'center', justifyContent: 'center', bgcolor: 'rgba(0,0,0,0.1)', minHeight: 200 }}>
                <CircularProgress size={32} />
            </Box>
        );
    }

    if (error || !videoUrl) {
        return <Box component="video" src={src || ''} poster={posterUrl} controls={controls} sx={sx} {...props} />;
    }

    return (
        <Box 
            component="video" 
            src={videoUrl} 
            poster={posterUrl}
            controls={controls}
            sx={sx} 
            {...props} 
        />
    );
};

export default VideoView;
