import React, { useState, useEffect, useCallback, useRef } from "react";
import {
  Box,
  Typography,
  IconButton,
  Badge,
  Popover,
  Drawer,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
  Avatar,
  Divider,
  useTheme,
  useMediaQuery,
} from "@mui/material";
import NotificationsNoneIcon from "@mui/icons-material/NotificationsNone";
import NotificationsActiveIcon from "@mui/icons-material/NotificationsActive";
import InfoIcon from "@mui/icons-material/Info";
import WarningIcon from "@mui/icons-material/Warning";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import ErrorIcon from "@mui/icons-material/Error";
import CloseIcon from "@mui/icons-material/Close";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import { apiGetJson, BASE_URL } from "../../utils/apiClient";

const getRelativeTime = (dateString) => {
  if (!dateString) return "";
  const now = new Date();
  const date = new Date(dateString);
  const diffInSeconds = Math.floor((now - date) / 1000);

  if (diffInSeconds < 60) return "just now";
  if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)} minutes ago`;
  if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)} hours ago`;
  if (diffInSeconds < 2592000) return `${Math.floor(diffInSeconds / 86400)} days ago`;
  return date.toLocaleDateString();
};

const getNotificationIcon = (type) => {
  switch (type) {
    case "success":
    case "registration":
    case "subscription":
      return <CheckCircleIcon sx={{ color: "#4CC66E" }} />;
    case "warning":
    case "missed_workout":
      return <WarningIcon sx={{ color: "#FFB020" }} />;
    case "error":
    case "payment_failed":
      return <ErrorIcon sx={{ color: "#D14343" }} />;
    case "info":
    case "update":
    default:
      return <InfoIcon sx={{ color: "#3B82F6" }} />;
  }
};

const NotificationMenu = () => {
  const theme = useTheme();
  const [notifications, setNotifications] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const token = useSelector((state) => state.auth.token);
  const hasFetchedRef = useRef(false);

  const fetchNotifications = useCallback(async () => {
    if (!token) return;
    setIsLoading(true);
    try {
      const json = await apiGetJson('/notifications', token, {
        tab: 'all',
        limit: 50,
        offset: 0,
      });
      setNotifications(json.data?.notifications || []);
      hasFetchedRef.current = true;
    } catch (err) {
      console.error("Error fetching notifications:", err);
    } finally {
      setIsLoading(false);
    }
  }, [token]);

  useEffect(() => {
    if (token && !hasFetchedRef.current) {
      fetchNotifications();
    }
  }, [token, fetchNotifications]);

  useEffect(() => {
    if (!token) {
      hasFetchedRef.current = false;
      setNotifications([]);
    }
  }, [token]);

  const handleClick = () => {
    navigate("/notifications");
  };

  const handleNotificationClick = async (notification) => {
    if (!notification.is_read) {
      // Optimistic update
      setNotifications((prev) =>
        prev.map((n) =>
          n.id === notification.id ? { ...n, is_read: true } : n
        )
      );

      try {
        const res = await fetch(`${BASE_URL}/notifications/${notification.id}/read`, {
          method: "PATCH",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });
        const json = await res.json();
        if (!res.ok || json.error) throw new Error(json.message);
      } catch (err) {
        console.error("Error marking notification as read:", err);
      }
    }
  };

  const handleMarkAllRead = async () => {
    // Optimistic update
    setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true })));

    try {
      const res = await fetch(`${BASE_URL}/notifications/read-all`, {
        method: "PATCH",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      const json = await res.json();
      if (!res.ok || json.error) throw new Error(json.message);
      toast.success("All notifications marked as read");
    } catch (err) {
      console.error("Error marking all read:", err);
      toast.error("Failed to mark all as read");
      fetchNotifications();
    }
  };

  const unreadCount = notifications.filter((n) => !n.is_read).length;

  return (
    <IconButton
      onClick={handleClick}
      sx={{
        color: unreadCount > 0 ? "#9F6EDA" : "#FFF",
        mr: { xs: 0.5, sm: 1.5 },
        backgroundColor: unreadCount > 0 ? "rgba(159, 110, 218, 0.1)" : "rgba(255,255,255,0.05)",
        "&:hover": {
           backgroundColor: "rgba(255,255,255,0.1)",
        }
      }}
    >
      <Badge
        badgeContent={unreadCount}
        color="error"
        sx={{
          "& .MuiBadge-badge": {
            backgroundColor: "#D14343",
            color: "#FFF",
            fontWeight: 600,
          },
        }}
      >
        {unreadCount > 0 ? <NotificationsActiveIcon /> : <NotificationsNoneIcon />}
      </Badge>
    </IconButton>
  );
};

export default NotificationMenu;
