
import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { Box, CircularProgress, Typography } from '@mui/material';
import { getSecureFileUrl, mediaSourceNeedsAuthorizedFetch } from '../utils/fileHelpers';
import { fetchSecureMediaBlobUrl } from '../utils/mediaCache';

const AudioView = ({ src, sx, ...props }) => {
    const [audioUrl, setAudioUrl] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(false);

    const token = useSelector((state) => state.auth.token);
    const userId = 1;

    useEffect(() => {
        let cancelled = false;

        if (!src) {
            setAudioUrl('');
            return undefined;
        }

        if (src.startsWith('http://') || src.startsWith('https://') || src.startsWith('blob:') || src.startsWith('data:')) {
            setAudioUrl(src);
            return undefined;
        }

        const resolved = getSecureFileUrl(src, userId);
        if (!resolved) {
            setAudioUrl('');
            return undefined;
        }
        if (!mediaSourceNeedsAuthorizedFetch(resolved)) {
            setAudioUrl(resolved);
            return undefined;
        }

        setLoading(true);
        setError(false);

        fetchSecureMediaBlobUrl(resolved, token)
            .then((objectUrl) => {
                if (!cancelled) {
                    setAudioUrl(objectUrl);
                }
            })
            .catch((err) => {
                console.error('Error loading secure audio:', err);
                if (!cancelled) {
                    setError(true);
                }
            })
            .finally(() => {
                if (!cancelled) {
                    setLoading(false);
                }
            });

        return () => {
            cancelled = true;
        };
    }, [src, userId, token]);

    if (loading) {
        return (
            <Box sx={{ ...sx, display: 'flex', alignItems: 'center', gap: 2 }}>
                <CircularProgress size={20} />
                <Typography variant="caption" sx={{ color: '#8B8D97' }}>Loading audio...</Typography>
            </Box>
        );
    }

    if (error || !audioUrl) {
        return <Box component="audio" src={src || ''} controls sx={sx} {...props} />;
    }

    return (
        <Box 
            component="audio" 
            src={audioUrl} 
            controls
            sx={sx} 
            {...props} 
        />
    );
};

export default AudioView;
