import React, { useMemo } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { Link as MuiLink, Box, useTheme } from "@mui/material";
import NavigateNextIcon from '@mui/icons-material/NavigateNext';

const routeLabels = {
  "/dashboard": "Dashboard",
  "/all-users": "All Users",
  "/deleted-users": "Deleted Users",
  "/exercises": "Exercises",
  "/goals": "Goals",
  "/quotes": "Motivational Quotes",
  "/badges": "Badges",
  "/rewards": "Rewards",
  "/leaderboard": "Leaderboard",
  "/feedback": "Feedback",
  "/notifications": "Notifications",
  "/broadcast-notifications": "Broadcast Notifications",
  "/send-notification": "Send Notification",
  "/app-tutorial": "App Tutorial",
  "/terms-and-conditions": "Terms & Conditions",
  "/privacy-policy": "Privacy Policy",
  "/onboarding-questions": "Onboarding Questions",
  "/legal": "Legal Settings",
};

const dynamicRouteLabels = [
  {
    test: /^\/all-users\/[^/]+$/,
    label: "User Details",
    parentPath: "/all-users",
  },
  {
    test: /^\/exercises\/edit\/[^/]+$/,
    label: "Edit Exercise",
    parentPath: "/exercises",
  },
  {
    test: /^\/exercises\/add$/,
    label: "Add Exercise",
    parentPath: "/exercises",
  },
  {
    test: /^\/goals\/add$/,
    label: "Add Goal",
    parentPath: "/goals",
  },
  {
    test: /^\/quotes\/add$/,
    label: "Add Quote",
    parentPath: "/quotes",
  },
  {
    test: /^\/onboarding-questions\/edit$/,
    label: "Edit Questions",
    parentPath: "/onboarding-questions",
  },
];

const isIdSegment = (segment) =>
  /^[a-f\d]{24}$/i.test(segment) ||
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(segment) ||
  /^\d+$/.test(segment);

const formatSegment = (segment) =>
  segment
    .replace(/-/g, " ")
    .replace(/\b\w/g, (char) => char.toUpperCase());

const singularize = (label) => {
  if (label.endsWith("ies")) return `${label.slice(0, -3)}y`;
  if (label.endsWith("s")) return label.slice(0, -1);
  return label;
};

const buildCrumbs = (pathname) => {
  const segments = pathname.split("/").filter(Boolean);
  const crumbs = [{ path: "/dashboard", label: "Dashboard", navigateTo: "/dashboard" }];

  if (segments.length === 0) {
    return crumbs;
  }

  const dynamic = dynamicRouteLabels.find((route) => route.test.test(pathname));
  if (dynamic) {
    const parentPath = dynamic.parentPath;
    if (parentPath && routeLabels[parentPath]) {
      crumbs.push({
        path: parentPath,
        label: routeLabels[parentPath],
        navigateTo: parentPath,
      });
    }
    crumbs.push({
      path: pathname,
      label: dynamic.label,
      navigateTo: parentPath || pathname,
    });
    return crumbs;
  }

  let currentPath = "";

  segments.forEach((segment, index) => {
    currentPath += `/${segment}`;

    if (currentPath === "/dashboard") {
      return;
    }

    if (isIdSegment(segment)) {
      return;
    }

    let label = routeLabels[currentPath];
    let navigateTo = currentPath;

    if (!label) {
      if (segment === "edit" || segment === "add") {
        const resourcePath = `/${segments[0]}`;
        const resourceLabel = routeLabels[resourcePath] || formatSegment(segments[0]);
        const singular = singularize(resourceLabel);
        label = segment === "edit" ? `Edit ${singular}` : `Add ${singular}`;
        navigateTo = resourcePath;
      } else {
        label = formatSegment(segment);
      }
    }

    const isLastMeaningful =
      index === segments.length - 1 ||
      segments.slice(index + 1).every(isIdSegment);

    crumbs.push({
      path: isLastMeaningful ? pathname : currentPath,
      label,
      navigateTo,
    });
  });

  return crumbs;
};

const BreadcrumbsTrail = () => {
  const theme = useTheme();
  const location = useLocation();
  const navigate = useNavigate();

  const hideBreadcrumbs = location.pathname === "/dashboard" || location.pathname === "/";

  const crumbs = useMemo(
    () => buildCrumbs(location.pathname),
    [location.pathname]
  );

  if (hideBreadcrumbs) {
    return null;
  }

  return (
    <Box
      sx={{
        mb: { xs: 2, md: 3 },
        px: { xs: 1, sm: 2},
        width: "100%",
      }}
    >
      <Box
        sx={{
          display: "flex",
          flexWrap: "wrap",
          alignItems: "center",
          gap: 1,
          background: "linear-gradient(180deg, rgba(6, 22, 10, 0.96) 0%, rgba(12, 36, 20, 0.90) 100%)",
          border: "1px solid rgba(255,255,255,0.12)",
          borderRadius: "24px",
          p: { xs: 1.25, sm: 1.5 },
          boxShadow: "0 24px 48px rgba(0,0,0,0.35)",
        }}
      >
        {crumbs.map((crumb, index) => {
          const isLast = index === crumbs.length - 1;
          const crumbContent = isLast ? (
            <Box
              sx={{
                px: 1.7,
                py: 0.7,
                borderRadius: "999px",
                bgcolor: theme.palette.primary.main,
                color: theme.palette.primary.contrastText,
                fontWeight: 700,
                fontSize: { xs: "0.8rem", sm: "0.95rem" },
                whiteSpace: "nowrap",
                boxShadow: "0 8px 18px rgba(76,198,110,0.22)",
              }}
            >
              {crumb.label}
            </Box>
          ) : (
            <MuiLink
              component="button"
              type="button"
              onClick={() => navigate(crumb.navigateTo ?? crumb.path)}
              underline="none"
              sx={{
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                px: 1.7,
                py: 0.7,
                borderRadius: "999px",
                bgcolor: "rgba(255,255,255,0.08)",
                color: "rgba(255,255,255,0.88)",
                fontWeight: 500,
                fontSize: { xs: "0.8rem", sm: "0.95rem" },
                textTransform: "none",
                whiteSpace: "nowrap",
                transition: "all 0.2s ease",
                '&:hover': {
                  bgcolor: "rgba(255,255,255,0.16)",
                  color: "#fff",
                },
              }}
            >
              {crumb.label}
            </MuiLink>
          );

          return (
            <Box key={`${crumb.path}-${index}`} sx={{ display: "inline-flex", alignItems: "center", gap: 0.75 }}>
              {index > 0 && (
                <NavigateNextIcon
                  sx={{ color: "rgba(255,255,255,0.55)", fontSize: { xs: 15, sm: 18 } }}
                />
              )}
              {crumbContent}
            </Box>
          );
        })}
      </Box>
    </Box>
  );
};

export default BreadcrumbsTrail;
