
import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { Avatar, Tooltip } from '@mui/material';
import { getSecureFileUrl, mediaSourceNeedsAuthorizedFetch } from '../utils/fileHelpers';
import { fetchSecureMediaBlobUrl } from '../utils/mediaCache';
import AccountCircleIcon from '@mui/icons-material/AccountCircle';
import ImagePreviewModal from './ImagePreviewModal';

const AvatarView = ({
  src,
  user: userProp,
  alt,
  sx,
  children,
  previewable = true,
  previewTitle,
  disablePreview = false,
  onClick,
  ...props
}) => {
  const [imageUrl, setImageUrl] = useState('');
  const [error, setError] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);

  const token = useSelector((state) => state.auth.token);

  const userId = 1;

  const resolvedSrc = src || userProp?.profile?.profile_image || userProp?.profile_image;
  const canPreview = previewable && !disablePreview && Boolean(imageUrl) && !error;

  useEffect(() => {
    let cancelled = false;

    if (!resolvedSrc) {
      setImageUrl('');
      setError(false);
      return undefined;
    }

    if (resolvedSrc.startsWith('http://') || resolvedSrc.startsWith('https://') || resolvedSrc.startsWith('blob:') || resolvedSrc.startsWith('data:')) {
      setImageUrl(resolvedSrc);
      setError(false);
      return undefined;
    }

    const resolved = getSecureFileUrl(resolvedSrc, userId);
    if (!resolved) {
      setImageUrl('');
      setError(false);
      return undefined;
    }
    if (!mediaSourceNeedsAuthorizedFetch(resolved)) {
      setImageUrl(resolved);
      setError(false);
      return undefined;
    }

    setError(false);

    fetchSecureMediaBlobUrl(resolved, token)
      .then((objectUrl) => {
        if (!cancelled) {
          setImageUrl(objectUrl);
        }
      })
      .catch((err) => {
        console.error('Error loading secure avatar:', err);
        if (!cancelled) {
          setError(true);
          setImageUrl('');
        }
      });

    return () => {
      cancelled = true;
    };
  }, [resolvedSrc, userId, token]);

  const handleClick = (event) => {
    if (onClick) {
      onClick(event);
    }

    if (canPreview) {
      event.stopPropagation();
      setPreviewOpen(true);
    }
  };

  const avatar = (
    <Avatar
      src={error ? '' : imageUrl}
      alt={alt}
      onClick={canPreview || onClick ? handleClick : undefined}
      sx={{
        bgcolor: '#1a1a1a',
        ...(canPreview && {
          cursor: 'pointer',
          transition: 'transform 0.2s ease, box-shadow 0.2s ease',
          '&:hover': {
            transform: 'scale(1.04)',
            boxShadow: '0 0 0 2px rgba(76, 198, 110, 0.35)',
          },
        }),
        ...sx,
      }}
      {...props}
    >
      {children ? children : (!imageUrl && !error && <AccountCircleIcon sx={{ fontSize: sx?.width || 40 }} />)}
    </Avatar>
  );

  return (
    <>
      {canPreview ? (
        <Tooltip title="Click to view full image" arrow>
          {avatar}
        </Tooltip>
      ) : (
        avatar
      )}

      <ImagePreviewModal
        open={previewOpen}
        onClose={() => setPreviewOpen(false)}
        src={resolvedSrc}
        displayUrl={imageUrl}
        alt={alt || previewTitle || 'Profile image'}
        title={previewTitle || alt || 'Profile Image'}
      />
    </>
  );
};

export default AvatarView;
