import React, { useMemo, useState, useEffect } from "react";
import {
  Box,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Collapse,
  Typography,
} from "@mui/material";
import { ExpandLess, ExpandMore } from "@mui/icons-material";
import { useNavigate, useLocation } from "react-router-dom";
import { useTheme } from "@mui/material/styles";

import {
  Group as UsersIcon,
  PersonOff as DeletedUsersIcon,
  Dashboard as DashboardIcon,
  Category as ContentIcon,
  VideoLibrary as VideoLibraryIcon,
  FitnessCenter as WorkoutIcon,
  Policy as LegalIcon,
  Security as PrivacyIcon,
  Gavel as TermsIcon,
  Email as MessageIcon,
  EmojiEvents as RewardsIcon,
  MonetizationOn as MoneyIcon,
  Leaderboard as LeaderboardIcon,
  Notifications as NotificationsIcon,
  Flag as GoalIcon,
  FormatQuote as QuoteIcon,
  HelpOutline as QuestionIcon,
  CreditCard as PaymentsIcon,
  Paid as CoinsIcon,
  Insights as AnalyticsIcon,
  LocalFireDepartment as StreakIcon,
  SmartToy as AiIcon,
  Article as LogsIcon,
} from "@mui/icons-material";

const Sidebar = ({ mobile, onClose }) => {
  const theme = useTheme();
  const navigate = useNavigate();
  const location = useLocation();
  const menuItems = useMemo(
    () => [
      {
        key: "dashboard_root",
        label: "Dashboard",
        muiIcon: DashboardIcon,
        path: "/dashboard",
      },
      // {
      //   key: "user_management",
      //   label: "User Management",
      //   muiIcon: UsersIcon,
      //   children: [
      //     {
      //       key: "all_users",
      //       label: "All Users",
      //       path: "/all-users",
      //       muiIcon: UsersIcon,
      //     },
      //     {
      //       key: "deleted_users",
      //       label: "Deleted Users",
      //       path: "/deleted-users",
      //       muiIcon: DeletedUsersIcon,
      //     },
      //   ],
      // },


      {
        key: "all_users",
        label: "Users",
        path: "/all-users",
        muiIcon: UsersIcon,
      },
      {
        key: "content_management",
        label: "Content Management",
        muiIcon: ContentIcon,
        children: [
         
          {
            key: "exercises",
            label: "Exercise",
            path: "/exercises",
            muiIcon: WorkoutIcon,
          },
          {
            key: "goals",
            label: "Goals",
            path: "/goals",
            muiIcon: GoalIcon,
          },
          {
            key: "app_tutorial",
            label: "App Tutorial",
            path: "/app-tutorial",
            muiIcon: VideoLibraryIcon,
          },
          {
            key: "quotes",
            label: "Motivational Quotes",
            path: "/quotes",
            muiIcon: QuoteIcon,
          },
          // {
          //   key: "onboarding_questions",
          //   label: "Onboarding Questions",
          //   path: "/onboarding-questions",
          //   muiIcon: QuestionIcon,
          // },
        ],
      },
      {
        key: "rewards_management",
        label: "Rewards Management",
        muiIcon: RewardsIcon,
        children: [
          {
            key: "badges",
            label: "Badges",
            path: "/badges",
            muiIcon: RewardsIcon,
          },
          {
            key: "rewards",
            label: "Rewards",
            path: "/rewards",
            muiIcon: MoneyIcon,
          },
        ],
      },
      {
        key: "leaderboard",
        label: "Leaderboard",
        muiIcon: LeaderboardIcon,
        path: "/leaderboard",
      },
      {
        key: "payments",
        label: "Payments & Subscriptions",
        muiIcon: PaymentsIcon,
        path: "/payments",
      },
      {
        key: "coins",
        label: "Coins Economy",
        muiIcon: CoinsIcon,
        path: "/coins",
      },
      {
        key: "analytics",
        label: "Analytics",
        muiIcon: AnalyticsIcon,
        children: [
          {
            key: "workout_analytics",
            label: "Workout Analytics",
            path: "/workout-analytics",
            muiIcon: WorkoutIcon,
          },
          {
            key: "streaks_retention",
            label: "Streaks & Retention",
            path: "/streaks-retention",
            muiIcon: StreakIcon,
          },
          {
            key: "ai_monitoring",
            label: "AI Monitoring",
            path: "/ai-monitoring",
            muiIcon: AiIcon,
          },
        ],
      },
      {
        key: "feedback",
        label: "Feedback",
        muiIcon: MessageIcon,
        path: "/feedback",
      },
      // {
      //   key: "notifications_feed",
      //   label: "Notifications",
      //   muiIcon: NotificationsIcon,
      //   path: "/notifications",
      // },
      {
        key: "broadcast_notifications",
        label: "Broadcast Notifications",
        muiIcon: NotificationsIcon,
        path: "/broadcast-notifications",
      },
      {
        key: "legal_management",
        label: "Legal",
        muiIcon: LegalIcon,
        path: "/legal",
      }
      // {
      //   key: "system_logs",
      //   label: "System Logs",
      //   muiIcon: LogsIcon,
      //   path: "/system-logs",
      // },
    ],
    []
  );

  const [openMenus, setOpenMenus] = useState({});
  const selectedPath = location.pathname;

  useEffect(() => {
    const parent = menuItems.find(
      (item) =>
        item.children && item.children.some((c) => c.path === selectedPath)
    );
    if (parent) setOpenMenus({ [parent.key]: true });
  }, [selectedPath, menuItems]);

  const toggleMenu = (key) => {
    setOpenMenus((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <Box
      sx={{
        width: "100%",
        overflowX: "hidden",
        height: '100%',
        boxSizing: "border-box",
        backgroundColor: '#001e08ff',
        display: "flex",
        flexDirection: "column",
        pl: 1,
        pt: mobile ? '90px' : '20px', 
      }}
    >
      <Box sx={{ 
        flexGrow: 1, 
        overflowY: "auto", 
        overflowX: "hidden", 
        px: 1.5,
        "&::-webkit-scrollbar": {
          width: "4px",
          height: "0px", // Hides horizontal scrollbar completely
        },
        "&::-webkit-scrollbar-thumb": {
          backgroundColor: "rgba(255,255,255,0.1)",
          borderRadius: "4px",
        }
      }}>
        <List sx={{ py: 1 }}>
          {menuItems.map((item) => {
            const isChildActive = item.children?.some((c) => c.path === selectedPath);
            const isSelfActive = item.path === selectedPath;
            const isOpen = !!openMenus[item.key];
            const MuiIcon = item.muiIcon;

            return (
              <Box key={item.key} sx={{ mb: 1 }}>
                <ListItemButton
                  onClick={() => {
                    if (item.children) toggleMenu(item.key);
                    else if (item.path) navigate(item.path);
                  }}
                  sx={{
                    borderRadius: "10px",
                    px: 2,
                    py: 1.2,
                    position: "relative",
                    backgroundColor: isSelfActive 
                      ? "primary.main" 
                      : isChildActive 
                        ? "rgba(76, 198, 110, 0.1)" 
                        : "transparent",
                    transition: "all 0.2s ease-in-out",
                    "& .MuiListItemIcon-root": {
                      color: isSelfActive ? "#000000" : isChildActive ? "primary.main" : "text.secondary",
                    },
                    "& .MuiListItemText-primary": {
                      color: isSelfActive ? "#000000" : isChildActive ? "#FFFFFF" : "text.secondary",
                      fontWeight: (isSelfActive || isChildActive) ? 600 : 500,
                    },
                    "&:hover": {
                      backgroundColor: isSelfActive ? "primary.main" : "rgba(255, 255, 255, 0.08)",
                      "& .MuiListItemIcon-root": { color: isSelfActive ? "#000000" : "primary.main" },
                      "& .MuiListItemText-primary": { color: isSelfActive ? "#000000" : "#FFFFFF" },
                    },
                    "&::before": isSelfActive ? {
                      content: '""',
                      position: 'absolute',
                      left: 0,
                      top: '25%',
                      height: '50%',
                      width: '4px',
                      backgroundColor: '#000000',
                      borderRadius: '0 4px 4px 0',
                    } : {},
                  }}
                >
                  <ListItemIcon sx={{ minWidth: 35 }}>
                    {MuiIcon && <MuiIcon sx={{ fontSize: 22 }} />}
                  </ListItemIcon>

                  <ListItemText
                    primary={item.label}
                    primaryTypographyProps={{ 
                      fontSize: "13.5px", 
                      whiteSpace: 'nowrap',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis'
                    }}
                  />

                  {item.children && (
                    <Box sx={{ ml: 1, display: 'flex', color: isChildActive ? 'primary.main' : 'text.secondary' }}>
                      {isOpen ? <ExpandLess sx={{ fontSize: 20 }} /> : <ExpandMore sx={{ fontSize: 20 }} />}
                    </Box>
                  )}
                </ListItemButton>

                {item.children && (
                  <Collapse in={isOpen} timeout="auto" unmountOnExit>
                    <List component="div" disablePadding sx={{ mt: 0.5 }}>
                      {item.children.map((child) => {
                        const isChildSelected = child.path === selectedPath;
                        return (
                          <ListItemButton
                            key={child.key}
                            onClick={() => navigate(child.path)}
                            sx={{
                              mx: 1,
                              pl: 5,
                              pr: 1.5,
                              py: 0.8,
                              borderRadius: "8px",
                              position: "relative",
                              backgroundColor: isChildSelected ? "rgba(76, 198, 110, 0.12)" : "transparent",
                              "& .MuiListItemText-primary": {
                                color: isChildSelected ? "primary.main" : "text.secondary",
                                fontWeight: isChildSelected ? 600 : 400,
                                fontSize: "12.5px",
                                whiteSpace: 'nowrap'
                              },
                              "&:hover": {
                                backgroundColor: isChildSelected ? "rgba(76, 198, 110, 0.15)" : "rgba(255, 255, 255, 0.05)",
                                "& .MuiListItemText-primary": { color: "primary.main" },
                              },
                            }}
                          >
                            <ListItemText primary={child.label} />
                          </ListItemButton>
                        );
                      })}
                    </List>
                  </Collapse>
                )}
              </Box>
            );
          })}
        </List>
      </Box>
    </Box>

  );
};

export default Sidebar;
