import { useEffect, useRef } from 'react';
import useNetworkStatus from '../hooks/useNetworkStatus';
import { toast } from 'react-hot-toast';

const ConnectivityManager = () => {
  const { isOnline, isSlow } = useNetworkStatus();
  const offlineToastId = useRef(null);
  const slowToastId = useRef(null);
  const prevOnline = useRef(isOnline);

  useEffect(() => {
     if (!isOnline) {
      if (!offlineToastId.current) {
        offlineToastId.current = toast.error("No Internet Connection. Please check your network.", {
          id: 'offline-toast',
          duration: Infinity, 
          position: 'top-center',
          style: {
            background: '#D14343',
            color: '#fff',
            fontWeight: 600,
          }
        });
      }
    } else {
      
      if (offlineToastId.current) {
        toast.dismiss(offlineToastId.current);
        offlineToastId.current = null;
        
        if (!prevOnline.current) {
          toast.success("Internet Connection Restored", {
            duration: 3000,
            position: 'top-center',
            style: {
              background: '#4CC66E',
              color: '#fff',
              fontWeight: 600,
            }
          });
        }
      }
    }

    prevOnline.current = isOnline;
  }, [isOnline]);

  useEffect(() => {
    if (isOnline && isSlow) {
      if (!slowToastId.current) {
        slowToastId.current = toast.loading("Slow network connection detected...", {
          id: 'slow-network-toast',
          duration: 5000,
          position: 'top-right',
          style: {
            background: '#FFB020',
            color: '#1A1A1A',
            fontWeight: 600,
          }
        });
      }
    } else {
        if (slowToastId.current) {
            toast.dismiss(slowToastId.current);
            slowToastId.current = null;
        }
    }
  }, [isOnline, isSlow]);

  return null;
};

export default ConnectivityManager;
