import { initializeApp } from "firebase/app";
import { getMessaging, getToken, onMessage, isSupported } from "firebase/messaging";

const firebaseConfig = {
  apiKey: process.env.REACT_APP_FIREBASE_API_KEY || "YOUR_API_KEY_HERE",
  authDomain: process.env.REACT_APP_FIREBASE_AUTH_DOMAIN || "YOUR_AUTH_DOMAIN_HERE",
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID || "YOUR_PROJECT_ID_HERE",
  storageBucket: process.env.REACT_APP_FIREBASE_STORAGE_BUCKET || "YOUR_STORAGE_BUCKET_HERE",
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID || "YOUR_MESSAGING_SENDER_ID_HERE",
  appId: process.env.REACT_APP_FIREBASE_APP_ID || "YOUR_APP_ID_HERE"
};

let app;
let messaging;

try {
  app = initializeApp(firebaseConfig);
} catch (error) {
  console.error("Firebase initialization error", error);
}

// Initialize messaging only if supported and config is somewhat valid
export const initializeFirebaseMessaging = async () => {
    try {
        const supported = await isSupported();
        if (supported && app && firebaseConfig.apiKey !== "YOUR_API_KEY_HERE") {
            messaging = getMessaging(app);
            return messaging;
        }
        return null;
    } catch (e) {
        console.warn("Firebase messaging not supported or error", e);
        return null;
    }
};

export const requestForToken = async () => {
  try {
    const msg = await initializeFirebaseMessaging();
    if (!msg) {
        console.warn("Firebase messaging not initialized or not supported (check config and browser).");
        return null;
    }

    const permission = await Notification.requestPermission();
    if (permission === 'granted') {
        // We register SW manually to pass the environment variables to it
        const configStr = encodeURIComponent(JSON.stringify(firebaseConfig));
        const swRegistration = await navigator.serviceWorker.register(
            `/firebase-messaging-sw.js?firebaseConfig=${configStr}`
        );

        const currentToken = await getToken(msg, {
            vapidKey: process.env.REACT_APP_FIREBASE_VAPID_KEY || 'YOUR_VAPID_KEY_HERE',
            serviceWorkerRegistration: swRegistration
        });
        
        if (currentToken) {
            console.log('FCM Token retrieved successfully.');
            return currentToken;
        } else {
            console.log('No registration token available. Request permission to generate one.');
            return null;
        }
    } else {
        console.log('Notification permission denied.');
        return null;
    }
  } catch (err) {
    console.error('An error occurred while retrieving token.', err);
    return null;
  }
};

export const setupMessageListener = async (callback) => {
    const msg = await initializeFirebaseMessaging();
    if (!msg) return null;

    // onMessage returns an unsubscribe function
    return onMessage(msg, (payload) => {
        callback(payload);
    });
};
