const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const buildUrl = (path, params) => {
  const normalizedPath = path.startsWith('/') ? path : `/${path}`;
  const url = `${BASE_URL}${normalizedPath}`;
  if (!params) return url;

  const searchParams = params instanceof URLSearchParams
    ? params
    : new URLSearchParams(
        Object.entries(params).reduce((acc, [key, value]) => {
          if (value !== undefined && value !== null && value !== '') {
            acc[key] = String(value);
          }
          return acc;
        }, {}),
      );

  const query = searchParams.toString();
  return query ? `${url}?${query}` : url;
};

export const apiFetch = (path, token, options = {}) => {
  const { method = 'GET', params, body, headers = {} } = options;

  return fetch(buildUrl(path, params), {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...headers,
    },
    ...(body !== undefined ? { body: typeof body === 'string' ? body : JSON.stringify(body) } : {}),
  });
};

export const apiGetJson = async (path, token, params) => {
  const response = await apiFetch(path, token, { params });
  const json = await response.json().catch(() => ({}));

  if (!response.ok || json?.error) {
    const error = new Error(json?.message || json?.error || `Request failed: ${response.status}`);
    error.status = response.status;
    error.data = json;
    throw error;
  }

  return json;
};

export const apiGet = apiFetch;
export { BASE_URL, buildUrl };
