import { Navigate, useLocation } from "react-router-dom";
import { useSelector } from "react-redux";

const PublicRoute = ({ children }) => {
  const token = useSelector((state) => state.auth.token);
  const location = useLocation();
  const path = location.pathname.replace(/\/$/, ""); // Remove trailing slash

  // Define paths that should NOT redirect even if a token exists
  const authProgressPaths = [
    "/forget-password",
    "/forget-set-password",
    "/verification",
    "/reset-password",
    "/signup-landingpage",
    "/signup",
    "/plans",
    "/checkout",
    "/payment-success",
    "/payment-cancel",
    "/app-signup",
    "/app-plans",
    "/app-payment-success",
    "/app-payment-cancel"
  ];

  const isAuthProgressPath = authProgressPaths.includes(path);

  if (token && !isAuthProgressPath) {
    return <Navigate to="/dashboard" replace />;
  }

  return children;
};

export default PublicRoute;
