import React, { useCallback, useState } from 'react';
import { 
    Box, 
    Typography, 
    CircularProgress, 
    alpha, 
    IconButton,
    LinearProgress
} from '@mui/material';
import { 
    CloudUpload as CloudUploadIcon, 
    Close as CloseIcon
} from '@mui/icons-material';
import { useDropzone } from 'react-dropzone';
import { toast } from 'react-hot-toast';
import { useSelector } from 'react-redux';

import { UPLOAD_PLAIN_URL, extractUploadedFileUrl } from '../utils/fileHelpers';
import ImageView from './ImageView';
import VideoView from './VideoView';
import AudioView from './AudioView';

const FileUpload = ({ 
    folderName = 'general', 
    onUploadSuccess, 
    maxFiles = 1,
    maxSizeMB = 5,
    accept = { 'image/*': [] },
    helperText = "SVG, PNG, JPG or GIF (max. 5MB)",
    existingImageUrl = null,
    onRemove = null,
    shape = 'rect'
}) => {
    const [isUploading, setIsUploading] = useState(false);
    const [uploadProgress, setUploadProgress] = useState(0);

    const token = useSelector((state) => state.auth.token);
    const isCircle = shape === 'circle';

    const onDrop = useCallback(async (acceptedFiles) => {
        if (!acceptedFiles || acceptedFiles.length === 0) return;
        
        
        const oversizedFiles = acceptedFiles.filter(file => file.size > maxSizeMB * 1024 * 1024);
        if (oversizedFiles.length > 0) {
            toast.error(`File is too large. Maximum allowed size is ${maxSizeMB}MB`);
            return;
        }

        const filesToUpload = maxFiles === 1 ? [acceptedFiles[0]] : acceptedFiles;

        setIsUploading(true);
        setUploadProgress(0); 

        try {
            const uploadedUrls = [];

            for (const file of filesToUpload) {
                const formData = new FormData();
                formData.append('file', file);

                const headers = {};
                if (token) {
                    headers.Authorization = `Bearer ${token}`;
                }

                const response = await fetch(UPLOAD_PLAIN_URL, {
                    method: 'POST',
                    headers,
                    body: formData
                });

                const result = await response.json().catch(() => ({}));
                const fileUrl = extractUploadedFileUrl(result);

                if (response.ok && !result.error && fileUrl) {
                    uploadedUrls.push(fileUrl);
                } else {
                    throw new Error(result.message || result.error || 'Upload failed');
                }
            }

            setUploadProgress(100);

            if (maxFiles === 1) {
                onUploadSuccess(uploadedUrls[0] || '');
            } else {
                onUploadSuccess(uploadedUrls);
            }
            toast.success('Uploaded successfully');
        } catch (error) {
            console.error('Upload error:', error);
            toast.error(error.message || 'Error occurred during upload');
        } finally {
            setTimeout(() => {
                setIsUploading(false);
                setUploadProgress(0);
            }, 500);
        }
    }, [maxFiles, maxSizeMB, onUploadSuccess, token]);

    const { getRootProps, getInputProps, isDragActive, isDragReject } = useDropzone({
        onDrop,
        accept,
        maxFiles,
        disabled: isUploading,
        onDropRejected: () => {
            toast.error(`Invalid file type or too many files. Max allowed: ${maxFiles}`);
        }
    });

    return (
        <Box sx={{ width: isCircle ? 220 : '100%', fontFamily: "'Montserrat', sans-serif" }}>
            {existingImageUrl && !isUploading ? (
                  <Box sx={{ 
                    position: 'relative', 
                    borderRadius: isCircle ? '50%' : '12px', 
                    overflow: 'hidden',
                    border: '1px solid #474747',
                    width: isCircle ? 220 : '100%',
                    height: isCircle ? 220 : 200,
                    bgcolor: '#000000',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    transition: 'all 0.3s ease',
                    '&:hover .preview-overlay': { opacity: 1 }
                }}>
                    {accept && Object.keys(accept).some(key => key.includes('video')) ? (
                        <VideoView 
                            src={existingImageUrl}
                            sx={{
                                width: '100%',
                                height: '100%',
                                objectFit: 'contain',
                                p: 1
                            }}
                        />
                    ) : accept && Object.keys(accept).some(key => key.includes('audio')) ? (
                        <AudioView 
                            src={existingImageUrl}
                            sx={{
                                width: '100%',
                                p: 2
                            }}
                        />
                    ) : (
                        <ImageView
                            src={existingImageUrl}
                            previewTitle="Uploaded image"
                            sx={{
                                width: '100%',
                                height: '100%',
                                objectFit: 'contain',
                                p: 1
                            }}
                        />
                    )}
                    
                    <Box className="preview-overlay" sx={{
                        position: 'absolute',
                        inset: 0,
                        bgcolor: 'rgba(0, 0, 0, 0.6)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        opacity: 0,
                        transition: 'opacity 0.2s ease',
                        backdropFilter: 'blur(2px)'
                    }}>
                        <Box sx={{ display: 'flex', gap: 1.5 }}>
                            <Box 
                                {...getRootProps()}
                                sx={{ 
                                    bgcolor: '#4CC66E', 
                                    color: '#000', 
                                    px: 2.5, 
                                    py: 1, 
                                    borderRadius: '8px', 
                                    fontWeight: 700, 
                                    fontSize: '0.75rem',
                                    cursor: 'pointer',
                                    '&:hover': { bgcolor: '#3EB05D' }
                                }}
                            >
                                <input {...getInputProps()} />
                                Change File
                            </Box>
                            
                            {onRemove && (
                                <IconButton 
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        onRemove();
                                    }}
                                    sx={{
                                        bgcolor: 'rgba(255, 80, 80, 0.2)',
                                        color: '#FF5050',
                                        '&:hover': { bgcolor: '#FF5050', color: '#fff' },
                                        borderRadius: '8px',
                                        width: 36,
                                        height: 36
                                    }}
                                    size="small"
                                >
                                    <CloseIcon fontSize="small" />
                                </IconButton>
                            )}
                        </Box>
                    </Box>
                </Box>
            ) : (
                   <Box
                    {...getRootProps()}
                    sx={{
                        border: `2px dashed ${
                           isDragReject ? '#FF5050' :
                           isDragActive ? '#4CC66E' : 
                           '#474747'
                        }`,
                        borderRadius: isCircle ? '50%' : '16px',
                        p: 4,
                        textAlign: 'center',
                        cursor: isUploading ? 'not-allowed' : 'pointer',
                        bgcolor: isDragActive ? 'rgba(76, 198, 110, 0.04)' : '#000000',
                        transition: 'all 0.2s ease-in-out',
                        '&:hover': {
                            bgcolor: isUploading ? '#000000' : 'rgba(76, 198, 110, 0.04)',
                            borderColor: isUploading ? '#474747' : '#4CC66E',
                        },
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'center',
                        width: isCircle ? 220 : '100%',
                        minHeight: isCircle ? 220 : 180,
                        position: 'relative'
                    }}
                >
                    <input {...getInputProps()} />
                    
                    {isUploading ? (
                        <Box sx={{ width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                            <Box sx={{ position: 'relative', display: 'inline-flex', mb: 2 }}>
                                <CircularProgress 
                                    variant="determinate" 
                                    value={uploadProgress} 
                                    size={56} 
                                    thickness={5} 
                                    sx={{ color: '#4CC66E' }} 
                                />
                                <Box sx={{
                                    position: 'absolute',
                                    inset: 0,
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center'
                                }}>
                                    <Typography variant="caption" component="div" sx={{ color: '#4CC66E', fontWeight: 700 }}>
                                        {Math.round(uploadProgress)}%
                                    </Typography>
                                </Box>
                            </Box>
                            
                            <Typography sx={{ 
                                color: '#FFFFFF', 
                                fontWeight: 600, 
                                fontSize: '0.9rem',
                                fontFamily: "'Montserrat', sans-serif" 
                            }}>
                                Uploading ...
                            </Typography>
                            
                            <Box sx={{ width: '60%', mt: 2 }}>
                                <LinearProgress 
                                    variant="determinate" 
                                    value={uploadProgress} 
                                    sx={{ 
                                        height: 4, 
                                        borderRadius: 2,
                                        bgcolor: '#1A1A1A',
                                        '& .MuiLinearProgress-bar': { bgcolor: '#4CC66E' }
                                    }} 
                                />
                            </Box>
                        </Box>
                    ) : (
                        <>
                            <Box sx={{ 
                                width: 56, 
                                height: 56, 
                                borderRadius: '14px', 
                                bgcolor: alpha('#4CC66E', 0.1),
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                color: '#4CC66E',
                                mb: 2,
                                transition: 'all 0.3s ease'
                            }}>
                                <CloudUploadIcon sx={{ fontSize: 32 }} />
                            </Box>
                            <Typography sx={{ 
                                color: '#FFFFFF', 
                                fontWeight: 700, 
                                fontSize: '1rem',
                                mb: 0.5,
                                fontFamily: "'Montserrat', sans-serif" 
                            }}>
                                {isDragActive ? 'Drop to upload' : 'Click or Drag File'}
                            </Typography>
                            <Typography sx={{ 
                                color: '#8B8D97', 
                                fontSize: '0.8rem',
                                fontFamily: "'Montserrat', sans-serif" 
                            }}>
                                {helperText}
                            </Typography>
                        </>
                    )}
                </Box>
            )}
        </Box>
    );
};

export default FileUpload;
