
import './App.css';
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { ThemeProvider, CssBaseline } from "@mui/material";
import theme from "./theme";
import AuthLayout from './layouts.js/AuthLayout';
import DashboardLayout from './layouts.js/DashboardLayout';

import { toast, Toaster } from "react-hot-toast";
import PublicRoute from './Routes/PublicRoute';
import PrivateRoute from './Routes/PrivateRoutes';

import ScrollToTop from './components/ScrollToTop';
import SessionManager from './components/SessionManager';
import ConnectivityManager from './components/ConnectivityManager';
import RouteFallback from './components/RouteFallback';

import { LocalizationProvider } from "@mui/x-date-pickers";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";

import { lazy, Suspense, useEffect } from 'react';
import { SignupProvider } from './pages/SignupLandingPage/context/SignupContext';
import SignupLandingThemeWrapper from './pages/SignupLandingPage/SignupLandingThemeWrapper';

const Login = lazy(() => import('./pages/AuthPages/Login/Login'));
const ForgetPassword = lazy(() => import('./pages/AuthPages/Login/ForgetPassword'));
const VerificationScreen = lazy(() => import('./pages/AuthPages/Login/VerificationScreen'));
const ResetPassword = lazy(() => import('./pages/AuthPages/Login/Resetpassword'));
const ForgetSetPassword = lazy(() => import('./pages/AuthPages/Login/forgetSetPassword'));
const SignupLandingPage = lazy(() => import('./pages/SignupLandingPage/SignupLandingPage'));
const SignupLandingAuthLayout = lazy(() => import('./pages/SignupLandingPage/components/layout/AuthLayout'));
const SignupLandingPlans = lazy(() => import('./pages/SignupLandingPage/pages/PlansPage'));
const SignupLandingCheckout = lazy(() => import('./pages/SignupLandingPage/pages/CheckoutPage'));
const SignupLandingPaymentSuccess = lazy(() => import('./pages/SignupLandingPage/pages/PaymentSuccessPage'));
const SignupLandingPaymentCancel = lazy(() => import('./pages/SignupLandingPage/pages/PaymentCancelPage'));
const Signup = lazy(() => import('./pages/AppAuth/Signup/Signup'));
const Plans = lazy(() => import('./pages/AppAuth/Plans/Plans'));
const PaymentSuccess = lazy(() => import('./pages/AppAuth/Payment/PaymentSuccess'));
const PaymentCancel = lazy(() => import('./pages/AppAuth/Payment/PaymentCancel'));

const Dashboard = lazy(() => import('./pages/AdminPages/Dashboard/Dashboard'));
const AllUsers = lazy(() => import('./pages/AdminPages/UserManagement/AllUsers'));
const DeletedUsers = lazy(() => import('./pages/AdminPages/UserManagement/DeletedUsers'));
const UserDetails = lazy(() => import('./pages/AdminPages/UserManagement/UserDetails'));
const Exercises = lazy(() => import('./pages/AdminPages/Exercises/Exercises'));
const AddEditExercise = lazy(() => import('./pages/AdminPages/Exercises/AddEditExercise'));
const LegalSettings = lazy(() => import('./pages/AdminPages/Legal/LegalSettings'));
const FeedbackMessages = lazy(() => import('./pages/AdminPages/Feedback/Feedback'));
const BroadcastNotifications = lazy(() => import('./pages/AdminPages/Notifications/BroadcastNotifications'));
const NotificationsFeed = lazy(() => import('./pages/AdminPages/Notifications/NotificationsFeed'));
const SendNotification = lazy(() => import('./pages/AdminPages/Notifications/SendNotification'));
const Badges = lazy(() => import('./pages/AdminPages/Rewards/Badges'));
const Rewards = lazy(() => import('./pages/AdminPages/Rewards/Rewards'));
const Leaderboard = lazy(() => import('./pages/AdminPages/Rewards/Leaderboard'));
const AppTutorial = lazy(() => import('./pages/AdminPages/AppTutorial/AppTutorial'));
const Goals = lazy(() => import('./pages/AdminPages/Goals/Goals'));
const AddGoals = lazy(() => import('./pages/AdminPages/Goals/AddGoals'));
const Quotes = lazy(() => import('./pages/AdminPages/Quotes/Quotes'));
const AddQuotes = lazy(() => import('./pages/AdminPages/Quotes/AddQuotes'));
const SystemLogs = lazy(() => import('./pages/AdminPages/Logs/SystemLogs'));
const Payments = lazy(() => import('./pages/AdminPages/Payments/Payments'));
const Coins = lazy(() => import('./pages/AdminPages/Coins/Coins'));
const WorkoutAnalytics = lazy(() => import('./pages/AdminPages/Analytics/WorkoutAnalytics'));
const StreaksRetention = lazy(() => import('./pages/AdminPages/Analytics/StreaksRetention'));
const AiMonitoring = lazy(() => import('./pages/AdminPages/Analytics/AiMonitoring'));

function App() {
  useEffect(() => {
    let unsubscribe = null;

    const setupFirebase = async () => {
      try {
        const { setupMessageListener } = await import('./firebase');
        unsubscribe = await setupMessageListener((payload) => {
          console.log('[App.js] Foreground message received: ', payload);
          toast(
            (t) => (
              <span style={{ display: 'flex', flexDirection: 'column' }}>
                <b>{payload.notification?.title || "New Notification"}</b>
                <span style={{ fontSize: '0.9em', marginTop: '4px' }}>
                  {payload.notification?.body || ""}
                </span>
              </span>
            ),
            {
              duration: 6000,
              position: 'top-center',
              style: {
                background: '#1A1A1A',
                color: '#fff',
                border: '1px solid #4CC66E',
                cursor: 'pointer'
              },
            }
          );
        });
      } catch (err) {
        console.warn("Failed to setup firebase listener", err);
      }
    };

    setupFirebase();

    return () => {
      if (typeof unsubscribe === 'function') {
        unsubscribe();
      }
    };
  }, []);

  return (
    <LocalizationProvider dateAdapter={AdapterDayjs}>
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <SessionManager />
        <ConnectivityManager />
        <Router>
          <Toaster />
          <ScrollToTop />
          <Suspense fallback={<RouteFallback />}>
            <SignupProvider>
              <Routes>
                <Route
                  path="/"
                  element={
                    <PublicRoute>
                      <SignupLandingPage />
                    </PublicRoute>
                  }
                />
                <Route path="/signup-landingpage" element={<Navigate to="/" replace />} />
                <Route path="/signup" element={<Navigate to="/" replace />} />
                <Route
                  element={
                    <PublicRoute>
                      <SignupLandingThemeWrapper>
                        <SignupLandingAuthLayout />
                      </SignupLandingThemeWrapper>
                    </PublicRoute>
                  }
                >
                  <Route path="/plans" element={<SignupLandingPlans />} />
                  <Route path="/checkout" element={<SignupLandingCheckout />} />
                  <Route path="/payment-success" element={<SignupLandingPaymentSuccess />} />
                  <Route path="/payment-cancel" element={<SignupLandingPaymentCancel />} />
                </Route>

                <Route element={
                <PublicRoute>
                  <AuthLayout />
                </PublicRoute>
              }>
                <Route path="/login" element={<Login />} />
                <Route path="/app-signup" element={<Signup />} />
                <Route path="/app-plans" element={<Plans />} />
                <Route path="/app-payment-success" element={<PaymentSuccess />} />
                <Route path="/app-payment-cancel" element={<PaymentCancel />} />
                <Route path="/forget-password" element={<ForgetPassword />} />
                <Route path="/forget-set-password" element={<ForgetSetPassword />} />
                <Route path='/verification' element={<VerificationScreen />} />
                <Route path='/reset-password' element={<ResetPassword />} />
              </Route>

              <Route element={
                <PrivateRoute>
                  <DashboardLayout />
                </PrivateRoute>
              }>
                <Route path="/dashboard" element={<Dashboard />} />
                <Route path="/all-users" element={<AllUsers />} />
                <Route path="/all-users/:id" element={<UserDetails />} />
                <Route path="/deleted-users" element={<DeletedUsers />} />
                <Route path="/exercises" element={<Exercises />} />
                <Route path="/exercises/add" element={<AddEditExercise />} />
                <Route path="/exercises/edit/:id" element={<AddEditExercise />} />
                <Route path="/goals" element={<Goals />} />
                <Route path="/goals/add" element={<AddGoals />} />
                <Route path="/quotes" element={<Quotes />} />
                <Route path="/quotes/add" element={<AddQuotes />} />
                <Route path="/badges" element={<Badges />} />
                <Route path="/rewards" element={<Rewards />} />
                <Route path="/leaderboard" element={<Leaderboard />} />
                <Route path="/feedback" element={<FeedbackMessages />} />
                <Route path="/notifications" element={<NotificationsFeed />} />
                <Route path="/broadcast-notifications" element={<BroadcastNotifications />} />
                <Route path="/send-notification" element={<PrivateRoute><SendNotification /></PrivateRoute>} />
                <Route path="/app-tutorial" element={<AppTutorial />} />
                <Route path="/legal" element={<LegalSettings />} />
                <Route path="/payments" element={<Payments />} />
                <Route path="/coins" element={<Coins />} />
                <Route path="/workout-analytics" element={<WorkoutAnalytics />} />
                <Route path="/streaks-retention" element={<StreaksRetention />} />
                <Route path="/ai-monitoring" element={<AiMonitoring />} />
                <Route path="/system-logs" element={<SystemLogs />} />
              </Route>
            </Routes>
            </SignupProvider>
          </Suspense>
        </Router>
      </ThemeProvider>
    </LocalizationProvider>
  );
}

export default App;
